Definition hex_bits_signed_forwards {n : Z} (bv : mword n) (*n >=? 0*) (*n >? 0*) : (Z * string) :=
   let len := length_mword (bv) in
   let s :=
     if eq_vec ((access_vec_dec (bv) ((Z.sub n (1))))) (('b"1")) then
       String.append ("-") ((hex_str ((Z.add ((uint ((not_vec (bv))))) (1)))))
     else hex_str ((uint (bv))) in
   ((length_mword (bv), s)).

Definition hex_bits_signed_forwards_matches {n : Z} (_ : mword n) (*n >=? 0*) (*n >? 0*) : bool :=
   true.

Definition hex_bits_signed_backwards {n0 : Z} '((n, str) : (Z * string)) (*n0 >=? 0*) (*n0 >? 0*)
: mword n0 :=
   if generic_eq ((string_take (str) (1))) ("-") then
     sub_vec ((zeros n0)) ((parse_hex_bits n0 ((string_drop (str) (1)))))
   else
     let parsed := parse_hex_bits n0 (str) in
     if eq_vec ((access_vec_dec (parsed) ((Z.sub n0 (1))))) (('b"0")) then parsed
     else zeros n0.

Definition hex_bits_signed_backwards_matches '((n, str) : (Z * string)) (*n0 >=? 0*) (*n0 >? 0*)
: bool :=
   if generic_eq ((string_take (str) (1))) ("-") then valid_hex_bits (n) ((string_drop (str) (1)))
   else if valid_hex_bits (n) (str) then
     let parsed := parse_hex_bits (n) (str) in
     eq_vec ((access_vec_dec (parsed) ((Z.sub (n) (1))))) (('b"0"))
   else false.

