#[export] Hint Unfold fp_eflag_inexact : sail.
Definition fp_eflag_overflow_and_inexact : fp_exception_flags :=
or_vec (fp_eflag_oveflow) (fp_eflag_inexact).
#[export] Hint Unfold fp_eflag_overflow_and_inexact : sail.
Definition fp_rounding_rne : fp_rounding_modes := ('b"00001").
#[export] Hint Unfold fp_rounding_rne : sail.
Definition fp_rounding_rna : fp_rounding_modes := ('b"00010").
#[export] Hint Unfold fp_rounding_rna : sail.
Definition fp_rounding_rdn : fp_rounding_modes := ('b"00011").
#[export] Hint Unfold fp_rounding_rdn : sail.
Definition fp_rounding_rup : fp_rounding_modes := ('b"00100").
#[export] Hint Unfold fp_rounding_rup : sail.
Definition fp_rounding_rtz : fp_rounding_modes := ('b"00101").
#[export] Hint Unfold fp_rounding_rtz : sail.
Definition fp_rounding_default : fp_rounding_modes := fp_rounding_rne.
#[export] Hint Unfold fp_rounding_default : sail.
Definition undefined_float_bits (atom_n : Z) : M (float_bits atom_n) :=
   (undefined_bitvector (1)) >>= fun (w__0 : mword 1) =>
   (undefined_bitvector
      ((if Z.eqb ((__id (atom_n))) (16) then 5
        else if Z.eqb ((__id (atom_n))) (32) then 8
        else if Z.eqb ((__id (atom_n))) (64) then 11
        else 15))) >>= fun (w__1 : mword ((if atom_n =? 16 then 5 else ((if atom_n =? 32 then 8 else ((if atom_n =?
     64 then 11 else 15))))))) =>
   (undefined_bitvector
      ((if Z.eqb ((__id (atom_n))) (16) then 10
        else if Z.eqb ((__id (atom_n))) (32) then 23
        else if Z.eqb ((__id (atom_n))) (64) then 52
        else 112))) >>= fun (w__2 : mword ((if atom_n =? 16 then 10 else ((if atom_n =? 32 then 23 else ((if atom_n =?
     64 then 52 else 112))))))) =>
   returnM (({| float_bits_sign := w__0;  float_bits_exp := w__1;  float_bits_mantissa := w__2 |})).

Definition float_decompose {n : Z} (op : mword n) (*n >=? 0*) (*member_Z_list n [16; 32; 64; 128]*)
: float_bits n :=
   let l__0 := length_mword (op) in
   if Z.eqb n (16) then
     {| float_bits_sign := subrange_vec_dec (op) (15) (15);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (14) (10));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (9) (0)) |}
   else if Z.eqb n (32) then
     {| float_bits_sign := subrange_vec_dec (op) (31) (31);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (30) (23));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (22) (0)) |}
   else if Z.eqb n (64) then
     {| float_bits_sign := subrange_vec_dec (op) (63) (63);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (62) (52));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (51) (0)) |}
   else
     {| float_bits_sign := subrange_vec_dec (op) (127) (127);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (126) (112));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (111) (0)) |}.

Definition float_compose {n : Z} (op : float_bits n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: mword n :=
   autocast (T := mword)
   (concat_vec (op.(float_bits_sign))
      ((concat_vec (op.(float_bits_exp)) (op.(float_bits_mantissa))))).

Definition float_has_max_exp {n : Z} (op : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   let fp := float_decompose (op) in
   let bitsize := length_mword (op) in
   let one := zero_extend ((('b"1")  : mword 1)) n in
   let two := shiftl (one) (1) in
   let max_exp := sub_vec ((shiftl (one) ((length_mword (fp.(float_bits_exp)))))) (two) in
   eq_vec (max_exp) ((zero_extend (fp.(float_bits_exp)) n)).

Definition is_lowest_one {n : Z} (op : mword n) (*n >=? 0*) (*0 <? n*) : bool :=
   eq_vec ((access_vec_dec (op) (0))) (('b"1")).

Definition is_highest_one {n : Z} (op : mword n) (*n >=? 0*) (*0 <? n*) : bool :=
   eq_vec ((access_vec_dec (op) ((Z.sub n (1))))) (('b"1")).

Definition is_all_ones {n : Z} (op : mword n) (*n >=? 0*) (*0 <? n*) : bool :=
   eq_vec (op) ((sail_ones n)).

Definition is_lowest_zero {n : Z} (op : mword n) (*n >=? 0*) (*0 <? n*) : bool :=
   eq_vec ((access_vec_dec (op) (0))) (('b"0")).

Definition is_highest_zero {n : Z} (op : mword n) (*n >=? 0*) (*0 <? n*) : bool :=
   eq_vec ((access_vec_dec (op) ((Z.sub n (1))))) (('b"0")).

Definition is_all_zeros {n : Z} (op : mword n) (*n >=? 0*) (*0 <? n*) : bool :=
   eq_vec (op) ((zeros n)).

Definition float_is_nan {ex341723_ : Z} (op : mword ex341723_)
(*member_Z_list ex341723_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_exp := exp; float_bits_mantissa := mantissa; float_bits_sign := _ |}) :=
     float_decompose (op) in
   andb ((is_all_ones (exp))) ((negb ((is_all_zeros (mantissa))))).

Definition float_is_snan {ex341740_ : Z} (op : mword ex341740_)
(*member_Z_list ex341740_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_mantissa := mantissa; float_bits_sign := _; float_bits_exp := _ |}) :=
     float_decompose (op) in
   andb ((float_is_nan (op))) ((is_highest_zero (mantissa))).

Definition float_is_qnan {ex341747_ : Z} (op : mword ex341747_)
(*member_Z_list ex341747_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_mantissa := mantissa; float_bits_sign := _; float_bits_exp := _ |}) :=
     float_decompose (op) in
   andb ((float_is_nan (op))) ((is_highest_one (mantissa))).

Definition float_is_inf {ex341754_ : Z} (op : mword ex341754_)
(*member_Z_list ex341754_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_exp := exp; float_bits_mantissa := mantissa; float_bits_sign := _ |}) :=
     float_decompose (op) in
   andb ((is_all_ones (exp))) ((is_all_zeros (mantissa))).

Definition float_is_positive {ex341761_ : Z} (op : mword ex341761_)
(*member_Z_list ex341761_ [16; 32; 64; 128]*)
: bool :=
   is_highest_zero (op).

Definition float_is_negative {ex341763_ : Z} (op : mword ex341763_)
(*member_Z_list ex341763_ [16; 32; 64; 128]*)
: bool :=
   is_highest_one (op).

Definition float_is_zero {ex341765_ : Z} (op : mword ex341765_)
(*member_Z_list ex341765_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_exp := exp; float_bits_mantissa := mantissa; float_bits_sign := _ |}) :=
     float_decompose (op) in
   andb ((is_all_zeros (exp))) ((is_all_zeros (mantissa))).

Definition float_is_normal {ex341772_ : Z} (op : mword ex341772_)
(*member_Z_list ex341772_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_exp := exp; float_bits_sign := _; float_bits_mantissa := _ |}) :=
     float_decompose (op) in
   andb ((negb ((is_all_ones (exp))))) ((negb ((is_all_zeros (exp))))).

Definition float_is_subnormal {ex341790_ : Z} (op : mword ex341790_)
(*member_Z_list ex341790_ [16; 32; 64; 128]*)
: bool :=
   let '({| float_bits_exp := exp; float_bits_mantissa := mantissa; float_bits_sign := _ |}) :=
     float_decompose (op) in
   andb ((is_all_zeros (exp))) ((negb ((is_all_zeros (mantissa))))).

Definition float_get_rounding '(tt : unit) : M (mword 5) :=
   ((read_reg fp_rounding_global)  : M (mword 5))  : M (mword 5).

Definition float_set_rounding (rm : mword 5) : M (unit) :=
   write_reg fp_rounding_global rm  : M (unit).

Definition float_is_lt_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   let fp_0 := float_decompose (op_0) in
   let fp_1 := float_decompose (op_1) in
   let is_zero := andb ((float_is_zero (op_0))) ((float_is_zero (op_1))) in
   let diff_sign_lt := andb ((is_lowest_one (fp_0.(float_bits_sign)))) ((negb (is_zero))) in
   let is_neg := is_lowest_one (fp_0.(float_bits_sign)) in
   let unsigned_lt := Z.ltb ((uint (op_0))) ((uint (op_1))) in
   let is_xor :=
     orb ((andb (is_neg) ((negb (unsigned_lt))))) ((andb ((negb (is_neg))) (unsigned_lt))) in
   let same_sign_lt := andb ((neq_vec (op_0) (op_1))) (is_xor) in
   if neq_vec (fp_0.(float_bits_sign)) (fp_1.(float_bits_sign)) then diff_sign_lt
   else same_sign_lt.

Definition float_is_eq_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   let is_zero := andb ((float_is_zero (op_0))) ((float_is_zero (op_1))) in
   orb ((eq_vec (op_0) (op_1))) (is_zero).

Definition float_is_ne_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   negb ((float_is_eq_internal (op_0) (op_1))).

Definition float_is_le_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   orb ((float_is_eq_internal (op_0) (op_1))) ((float_is_lt_internal (op_0) (op_1))).

Definition float_is_gt_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   negb ((float_is_le_internal (op_0) (op_1))).

Definition float_is_ge_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: bool :=
   negb ((float_is_lt_internal (op_0) (op_1))).

Definition float_propagate_nan {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: (mword n * mword 5) :=
   let is_snan := orb ((float_is_snan (op_0))) ((float_is_snan (op_1))) in
   let flags := if is_snan then fp_eflag_invalid else fp_eflag_none in
   let one := zero_extend ((('b"1")  : mword 1)) n in
   let fp_0 := float_decompose (op_0) in
   let mask := shiftl (one) ((Z.sub ((length_mword (fp_0.(float_bits_mantissa)))) (1))) in
   let op := if float_is_nan (op_0) then op_0 else op_1 in
   ((or_vec (op) (mask), flags)).

Definition float_rounding_increment {n : Z}
(sign : mword 1) (op : mword n) (rounding_mode : mword 5) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: mword n :=
   let bitsize := length_mword (op) in
   let fp := float_decompose (op) in
   let is_rne := eq_vec (rounding_mode) (fp_rounding_rne) in
   let is_rna := eq_vec (rounding_mode) (fp_rounding_rna) in
   let not_rne_and_rna := andb ((negb (is_rne))) ((negb (is_rna))) in
   let rounding_inf :=
     if eq_vec (sign) ((('b"1")  : mword 1)) then fp_rounding_rdn
     else fp_rounding_rup in
   let one := zero_extend ((('b"1")  : mword 1)) n in
   if andb (not_rne_and_rna) ((eq_vec (rounding_mode) (rounding_inf))) then
     sub_vec ((shiftl (one) ((Z.sub ((length_mword (fp.(float_bits_exp)))) (1))))) (one)
   else if andb (not_rne_and_rna) ((neq_vec (rounding_mode) (rounding_inf))) then zeros n
   else shiftl (one) ((Z.sub ((length_mword (fp.(float_bits_exp)))) (2))).

Definition float_compose_after_round {n : Z}
(sign : mword 1) (exp : mword n) (mantissa : mword n) (increment : mword n)
(rounding_mode : mword 5) (*n >=? 0*) (*member_Z_list n [16; 32; 64; 128]*)
: (mword n * mword 5) :=
   let bitsize := length_mword (mantissa) in
   let fp := float_decompose (mantissa) in
   let one := zero_extend ((('b"1")  : mword 1)) n in
   let zero := zero_extend ((('b"0")  : mword 1)) n in
   let round_mask :=
     sub_vec ((shiftl (one) ((Z.sub ((length_mword (fp.(float_bits_exp)))) (1))))) (one) in
   let round_bits := and_vec (mantissa) (round_mask) in
   let eflag := if is_all_zeros (round_bits) then fp_eflag_none else fp_eflag_inexact in
   let rne_mask := if eq_vec (rounding_mode) (fp_rounding_rne) then one else zero in
   let cst_mask := shiftl (one) ((Z.sub ((length_mword (fp.(float_bits_exp)))) (2))) in
   let xor_mask := xor_vec (round_bits) (cst_mask) in
   let not_mask := if is_all_zeros (xor_mask) then one else zero in
   let and_mask := and_vec (not_mask) (rne_mask) in
   let mantissa_mask := not_vec (and_mask) in
   let offset := Z.sub ((length_mword (fp.(float_bits_exp)))) (1) in
   let mantissa_round := shiftr ((add_vec (mantissa) (increment))) (offset) in
   let mantissa_new := and_vec (mantissa_round) (mantissa_mask) in
   let exp_new := if is_all_zeros (mantissa_new) then zeros n else exp in
   let exp_shift := shiftl (exp_new) ((length_mword (fp.(float_bits_mantissa)))) in
   let exp_and_mantissa := vector_truncate ((add_vec (exp_shift) (mantissa_new))) ((Z.sub n (1))) in
   ((autocast (T := mword)
   (concat_vec (sign) (exp_and_mantissa)), eflag)).

Definition float_get_sign_with_all_ones_exp {n : Z} (sign : mword 1) (op : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: mword n :=
   let bitsize := length_mword (op) in
   let fp := float_decompose (op) in
   let one := zero_extend ((('b"1")  : mword 1)) n in
   let all_ones := sub_vec ((shiftl (one) ((length_mword (fp.(float_bits_exp)))))) (one) in
   let all_ones_exp := shiftl (all_ones) ((length_mword (fp.(float_bits_mantissa)))) in
   autocast (T := mword)
   (concat_vec (sign) ((vector_truncate (all_ones_exp) ((Z.sub n (1)))))).

Definition float_round_and_compose {n : Z}
(sign : mword 1) (exp : mword n) (mantissa : mword n) (rounding_mode : mword 5) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: (mword n * mword 5) :=
   let op := mantissa in
   let fp := float_decompose (op) in
   let bitsize := length_mword (op) in
   let one := zero_extend ((('b"1")  : mword 1)) n in
   let zero := zero_extend ((('b"0")  : mword 1)) n in
   let three := zero_extend ((('b"11")  : mword 2)) n in
   let increment := float_rounding_increment (sign) (mantissa) (rounding_mode) in
   let exp_limit := sub_vec ((shiftl (one) ((length_mword (fp.(float_bits_exp)))))) (three) in
   let exp_reach_limit := negb ((Z.ltb ((uint (exp))) ((uint (exp_limit))))) in
   let exp_overflow := Z.gtb ((uint (exp))) ((uint (exp_limit))) in
   let mantissa_limit := shiftl (one) ((Z.sub n (1))) in
   let mantissa_overflow :=
     negb ((Z.gtb ((uint (mantissa_limit))) ((Z.add ((uint (mantissa))) ((uint (increment))))))) in
   if andb (exp_reach_limit) ((orb (exp_overflow) (mantissa_overflow))) then
     let result' := float_get_sign_with_all_ones_exp (sign) (op) in
     let tail := if is_all_zeros (increment) then one else zero in
     ((sub_vec (result') (tail), fp_eflag_overflow_and_inexact))
   else float_compose_after_round (sign) (exp) (mantissa) (increment) (rounding_mode).

Definition float_add_same_exp_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: M ((mword n * mword 5)) :=
   let fp_0 := float_decompose (op_0) in
   let fp_1 := float_decompose (op_1) in
   let bitsize := length_mword (op_0) in
   let mantissa_0 := zero_extend (fp_0.(float_bits_mantissa)) n in
   let mantissa_1 := zero_extend (fp_1.(float_bits_mantissa)) n in
   let mantissa_sum := add_vec (mantissa_0) (mantissa_1) in
   let sign := fp_0.(float_bits_sign) in
   let no_round := andb ((is_lowest_zero (mantissa_sum))) ((negb ((float_has_max_exp (op_0))))) in
   (if no_round then
      let mantissa_shift := shiftr (mantissa_sum) (1) in
      let mantissa_bitsize := length_mword (fp_0.(float_bits_mantissa)) in
      let exp :=
        add_vec (fp_0.(float_bits_exp))
          ((zero_extend ((('b"1")  : mword 1)) ((length_mword (fp_0.(float_bits_exp)))))) in
      let mantissa := vector_truncate (mantissa_shift) (mantissa_bitsize) in
      returnM ((autocast (T := mword)
      (concat_vec (sign) ((concat_vec (exp) (mantissa)))), fp_eflag_none))
    else
      let exp := zero_extend (fp_0.(float_bits_exp)) n in
      let shift_bitsize := Z.add ((length_mword (fp_0.(float_bits_mantissa)))) (1) in
      let one := zero_extend ((('b"1")  : mword 1)) n in
      let mantissa_offset := add_vec (mantissa_sum) ((shiftl (one) (shift_bitsize))) in
      let mantissa :=
        shiftl (mantissa_offset) ((Z.sub ((length_mword (fp_0.(float_bits_exp)))) (2))) in
      (float_get_rounding (tt)) >>= fun rm =>
      returnM ((float_round_and_compose (sign) (exp) (mantissa) (rm))))
    : M ((mword n * mword 5)).

Definition float_add_same_exp {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: M ((mword n * mword 5)) :=
   let bitsize := length_mword (op_0) in
   let fp_0 := float_decompose (op_0) in
   let fp_1 := float_decompose (op_1) in
   assert_exp (eq_vec (fp_0.(float_bits_exp)) (fp_1.(float_bits_exp))) "The exp of floating point must be same." >>
   let is_exp_0_all_ones := is_all_ones (fp_0.(float_bits_exp)) in
   let is_mantissa_all_zeros :=
     is_all_zeros ((or_vec (fp_0.(float_bits_mantissa)) (fp_1.(float_bits_mantissa)))) in
   (if is_all_zeros (fp_0.(float_bits_exp)) then
      returnM ((add_vec (op_0) ((zero_extend (fp_1.(float_bits_mantissa)) n)), fp_eflag_none))
    else if andb (is_exp_0_all_ones) (is_mantissa_all_zeros) then returnM ((op_0, fp_eflag_none))
    else if andb (is_exp_0_all_ones) ((negb (is_mantissa_all_zeros))) then
      returnM ((float_propagate_nan (op_0) (op_1)))
    else (float_add_same_exp_internal (op_0) (op_1))  : M ((mword n * mword 5)))
    : M ((mword n * mword 5)).

Definition float_add_less_than_exp {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: M ((mword n * mword 5)) :=
   let bitsize := length_mword (op_0) in
   let fp_0 := float_decompose (op_0) in
   let fp_1 := float_decompose (op_1) in
   assert_exp (Z.ltb ((uint (fp_0.(float_bits_exp)))) ((uint (fp_1.(float_bits_exp))))) "The exp of floating point op_0 must be less than op_1." >>
   let is_exp_all_ones := is_all_ones (fp_1.(float_bits_exp)) in
   let mantissa_shift :=
     shiftl (fp_1.(float_bits_mantissa)) ((Z.sub ((length_mword (fp_1.(float_bits_exp)))) (2))) in
   let is_nan := negb ((is_all_zeros (mantissa_shift))) in
   (if andb (is_exp_all_ones) (is_nan) then returnM ((float_propagate_nan (op_0) (op_1)))
    else if is_exp_all_ones then
      returnM ((float_get_sign_with_all_ones_exp (fp_0.(float_bits_sign)) (op_0), fp_eflag_none))
    else assert_exp' false "Not implemented yet." >>= fun _ => exit tt)
    : M ((mword n * mword 5)).

Definition float_add_diff_exp {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: M ((mword n * mword 5)) :=
   let bitsize := length_mword (op_0) in
   let fp_0 := float_decompose (op_0) in
   let fp_1 := float_decompose (op_1) in
   assert_exp (neq_vec (fp_0.(float_bits_exp)) (fp_1.(float_bits_exp))) "The exp of floating point cannot be same." >>
   (if Z.ltb ((uint (fp_0.(float_bits_exp)))) ((uint (fp_1.(float_bits_exp))))
      return
      M ((mword n * mword 5)) then
      (float_add_less_than_exp (op_0) (op_1))
       : M ((mword n * mword 5))
    else assert_exp' false "Not implemented yet." >>= fun _ => exit tt)
    : M ((mword n * mword 5)).

Definition float_add_internal {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: M ((mword n * mword 5)) :=
   let fp_0 := float_decompose (op_0) in
   let fp_1 := float_decompose (op_1) in
   assert_exp (eq_vec ((xor_vec (fp_0.(float_bits_sign)) (fp_1.(float_bits_sign))))
                 ((('b"0")
                  : mword 1))) "The sign of float add operand 0 and operand 1 must be the same." >>
   (if eq_vec (fp_0.(float_bits_exp)) (fp_1.(float_bits_exp)) return M ((mword n * mword 5)) then
      (float_add_same_exp (op_0) (op_1))
       : M ((mword n * mword 5))
    else (float_add_diff_exp (op_0) (op_1))  : M ((mword n * mword 5)))
    : M ((mword n * mword 5)).

Definition float_sub_internal {n : Z} (_op_0 : mword n) (_op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
: M ((mword n * mword 5)) :=
   assert_exp' false "Not implemented yet." >>= fun _ => exit tt.

Definition float_is_eq {n : Z} (op_0 : mword n) (op_1 : mword n) (*n >=? 0*)
(*member_Z_list n [16; 32; 64; 128]*)
