Definition undefined_float_class '(tt : unit) : M (float_class) :=
   (internal_pick
      ([float_class_negative_inf;
      float_class_negative_normal;
      float_class_negative_subnormal;
      float_class_negative_zero;
      float_class_positive_zero;
      float_class_positive_subnormal;
      float_class_positive_normal;
      float_class_positive_inf;
      float_class_snan;
      float_class_qnan]))
    : M (float_class).

Definition float_classify {ex342166_ : Z} (f : mword ex342166_)
(*member_Z_list ex342166_ [16; 32; 64; 128]*)
: M (float_class) :=
   (if float_is_snan (f) then returnM (float_class_snan)
    else if float_is_qnan (f) then returnM (float_class_qnan)
    else if float_is_zero (f) then
      returnM ((if float_is_positive (f) then float_class_positive_zero
                else float_class_negative_zero))
    else if float_is_subnormal (f) then
      returnM ((if float_is_positive (f) then float_class_positive_subnormal
                else float_class_negative_subnormal))
    else if float_is_normal (f) then
      returnM ((if float_is_positive (f) then float_class_positive_normal
                else float_class_negative_normal))
    else if float_is_inf (f) then
      returnM ((if float_is_positive (f) then float_class_positive_inf
                else float_class_negative_inf))
    else assert_exp' false "float_classify internal logic error" >>= fun _ => exit tt)
    : M (float_class).

