Definition reverse_bits {n : Z} (xs : mword n) (*n >=? 0*) (*n >? 0*) : mword n :=
   let ys : bits n := zeros' n in
   let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub n (1) in
   (foreach_Z_up loop_i_lower loop_i_upper 1 ys
     (fun i ys => update_vec_dec (ys) (i) ((access_vec_dec (xs) ((Z.sub ((Z.sub n (1))) (i))))))).

