Definition pmm_mode_forwards (arg_ : PointerMaskingMode) : mword 2 :=
   match arg_ with
   | PMM_Disabled => ('b"00")
   | PMM_Reserved => ('b"01")
   | PMM_PMLEN_7 => ('b"10")
   | PMM_PMLEN_16 => ('b"11")
   end.

Definition pmm_mode_backwards (arg_ : mword 2) : PointerMaskingMode :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"00")) then PMM_Disabled
   else if eq_vec (p0_) (('b"01")) then PMM_Reserved
   else if eq_vec (p0_) (('b"10")) then PMM_PMLEN_7
   else PMM_PMLEN_16.

Definition pmm_mode_forwards_matches (arg_ : PointerMaskingMode) : bool :=
   match arg_ with
   | PMM_Disabled => true
   | PMM_Reserved => true
   | PMM_PMLEN_7 => true
   | PMM_PMLEN_16 => true
   end.

Definition pmm_mode_backwards_matches (arg_ : mword 2) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"00")) then true
   else if eq_vec (p0_) (('b"01")) then true
   else if eq_vec (p0_) (('b"10")) then true
   else if eq_vec (p0_) (('b"11")) then true
   else false.

Definition is_supported_pmm (ext : PM_Ext) (pmm : PointerMaskingMode) : bool :=
   match (ext, pmm) with
   | (_, PMM_Disabled) => true
   | (_, PMM_Reserved) => false
   | (PM_SSNPM, PMM_PMLEN_7) => true
   | (PM_SSNPM, PMM_PMLEN_16) => true
   | (PM_SMMPM, PMM_PMLEN_7) => true
   | (PM_SMMPM, PMM_PMLEN_16) => true
   | (PM_SMNPM, PMM_PMLEN_7) => true
   | (PM_SMNPM, PMM_PMLEN_16) => true
   end.

