Definition write_ram
(wk : write_kind) '((Physaddr addr) : physaddr) (width : Z) (data : mword (8 * width)) (meta : unit)
(*width >=? 0*) (*(0 <? width) && (width <=? 4096)*)
: M (bool) :=
   match wk with
   | Write_plain =>
      returnM ((AK_explicit
                  (({| Explicit_access_kind_variety := AV_plain;
                       Explicit_access_kind_strength := AS_normal |}))))
   | Write_RISCV_release =>
      (internal_error ("core/phys_mem_interface.sail") (90) ("Write_RISCV_release is unused"))
       : M (Access_kind RISCV_strong_access)
   | Write_RISCV_strong_release =>
      (internal_error ("core/phys_mem_interface.sail") (91) ("Write_RISCV_strong_release is unused"))
       : M (Access_kind RISCV_strong_access)
   | Write_RISCV_conditional =>
      returnM ((AK_explicit
                  (({| Explicit_access_kind_variety := AV_exclusive;
                       Explicit_access_kind_strength := AS_normal |}))))
   | Write_RISCV_conditional_release =>
      returnM ((AK_explicit
                  (({| Explicit_access_kind_variety := AV_exclusive;
                       Explicit_access_kind_strength := AS_rel_or_acq |}))))
   | Write_RISCV_conditional_strong_release =>
      returnM ((AK_arch (({| RISCV_strong_access_variety := AV_exclusive |}))))
   end >>= fun (w__2 : Access_kind RISCV_strong_access) =>
   let request : Mem_write_request width 64 physaddrbits unit RISCV_strong_access :=
     {| Mem_write_request_access_kind := w__2;
        Mem_write_request_va := None;
        Mem_write_request_pa := addr;
        Mem_write_request_translation := tt;
        Mem_write_request_size := width;
        Mem_write_request_value := Some (data);
        Mem_write_request_tag := None |} in
   (sail_mem_write (request)) >>= fun (w__3 : result (option bool) unit) =>
   let w__4 : bool :=
     match w__3 with
     | Ok _ =>
        let '(_) := (__WriteRAM_Meta (addr) (width) (meta))  : unit in
        true
     | Err tt => false
     end in
   returnM (w__4).

