Definition read_ram (rk : read_kind) '((Physaddr addr) : physaddr) (width : Z) (read_meta : bool)
(*width >=? 0*) (*(0 <? width) && (width <=? 4096)*)
: M ((mword (8 * width) * unit)) :=
   let meta := if read_meta then __ReadRAM_Meta (addr) (width) else default_meta in
   match rk with
   | Read_plain =>
      returnM ((AK_explicit
                  (({| Explicit_access_kind_variety := AV_plain;
                       Explicit_access_kind_strength := AS_normal |}))))
   | Read_ifetch => returnM ((AK_ifetch (tt)))
   | Read_RISCV_acquire =>
      (internal_error ("core/phys_mem_interface.sail") (131) ("Read_RISCV_acquire is unused"))
       : M (Access_kind RISCV_strong_access)
   | Read_RISCV_strong_acquire =>
      (internal_error ("core/phys_mem_interface.sail") (132) ("Read_RISCV_strong_acquire is unused"))
       : M (Access_kind RISCV_strong_access)
   | Read_RISCV_reserved =>
      returnM ((AK_explicit
                  (({| Explicit_access_kind_variety := AV_exclusive;
                       Explicit_access_kind_strength := AS_normal |}))))
   | Read_RISCV_reserved_acquire =>
      returnM ((AK_explicit
                  (({| Explicit_access_kind_variety := AV_exclusive;
                       Explicit_access_kind_strength := AS_rel_or_acq |}))))
   | Read_RISCV_reserved_strong_acquire =>
      returnM ((AK_arch (({| RISCV_strong_access_variety := AV_exclusive |}))))
   end >>= fun (w__2 : Access_kind RISCV_strong_access) =>
   let request : Mem_read_request width 64 physaddrbits unit RISCV_strong_access :=
     {| Mem_read_request_access_kind := w__2;
        Mem_read_request_va := None;
        Mem_read_request_pa := addr;
        Mem_read_request_translation := tt;
        Mem_read_request_size := width;
        Mem_read_request_tag := false |} in
   (sail_mem_read (request)) >>= fun (w__3 : result ((mword (8 * width) * option bool)) unit) =>
   match w__3 with
   | Ok (value, _) => returnM ((value, meta))
   | Err tt => exit tt  : M ((mword (8 * width) * unit))
   end
    : M ((mword (8 * width) * unit)).

