Definition brev8 {m : Z} (input : mword m) (*m >=? 0*) (*(m >=? 0) && ((ZEuclid.modulo m 8) =? 0)*)
: mword m :=
   let output : bits m := zeros' m in
   let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub m (8) in
   (foreach_Z_up loop_i_lower loop_i_upper 8 output
     (fun i output =>
       update_subrange_vec_dec (output) ((Z.add (i) (7))) (i)
         ((reverse_bits ((autocast (T := mword) (subrange_vec_dec (input) ((Z.add (i) (7))) (i)))))))).

Definition carryless_mul {n : Z} (a : mword n) (b : mword n) (*n >=? 0*) (*n >? 0*) : mword (2 * n) :=
   let result' : bits (2 * n) := zeros' ((Z.mul (2) n)) in
   let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub n (1) in
   (foreach_Z_up loop_i_lower loop_i_upper 1 result'
     (fun i result' =>
       if eq_vec ((access_vec_dec (a) (i))) (('b"1")) then
         xor_vec (result') ((shiftl ((zero_extend' ((Z.mul (2) n)) (b))) (i)))
       else result')).

Definition carryless_mulr {n : Z} (a : mword n) (b : mword n) (*n >=? 0*) (*n >? 0*) : mword n :=
   let result' : bits n := zeros' n in
   let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub n (1) in
   (foreach_Z_up loop_i_lower loop_i_upper 1 result'
     (fun i result' =>
       if eq_vec ((access_vec_dec (a) (i))) (('b"1")) then
         xor_vec (result') ((shiftr (b) ((Z.sub ((Z.sub n (i))) (1)))))
       else result')).

Definition carryless_mul_reversed {n : Z} (a : mword n) (b : mword n) (*n >=? 0*) (*n >? 0*)
: mword n :=
   let prod := carryless_mul ((reverse_bits (a))) ((reverse_bits (b))) in
   reverse_bits ((autocast (T := mword) (subrange_vec_dec (prod) ((Z.sub n (1))) (0)))).

Definition mult_to_bits_half
(l : Z) (sign1 : Signedness) (sign2 : Signedness) (rs1_bits : mword l) (rs2_bits : mword l)
(result_part : VectorHalf) (*l >=? 0*) (*l >? 0*)
: mword l :=
   let rs1_int : Z := match sign1 with | Signed => sint (rs1_bits) | Unsigned => uint (rs1_bits) end in
   let rs2_int : Z := match sign2 with | Signed => sint (rs2_bits) | Unsigned => uint (rs2_bits) end in
   let result_wide := to_bits_truncate ((Z.mul (2) (l))) ((Z.mul (rs1_int) (rs2_int))) in
   match result_part with
   | High =>
      autocast (T := mword) (subrange_vec_dec (result_wide) ((Z.sub ((Z.mul (2) (l))) (1))) (l))
   | Low => autocast (T := mword) (subrange_vec_dec (result_wide) ((Z.sub (l) (1))) (0))
   end.

Definition cmulr_equivalence (a : mword 16) (b : mword 16) : bool :=
   eq_vec ((carryless_mul_reversed (a) (b))) ((carryless_mulr (a) (b))).

Definition rev8 {m : Z} (input : mword m) (*m >=? 0*) (*(m >=? 0) && ((ZEuclid.modulo m 8) =? 0)*)
: mword m :=
   let output : bits m := zeros' m in
   let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub m (8) in
   (foreach_Z_up loop_i_lower loop_i_upper 8 output
     (fun i output =>
       update_subrange_vec_dec (output) ((Z.add (i) (7))) (i)
         ((autocast (T := mword)
           (subrange_vec_dec (input) ((Z.sub ((Z.sub m (i))) (1))) ((Z.sub ((Z.sub m (i))) (8)))))))).

Definition count_ones {n : Z} (x : mword n) (*n >=? 0*) (*n >=? 0*) : M (Z) :=
   let count : Z := 0 in
   (let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub n (1) in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 count
     (fun i count =>
       (if eq_vec ((access_vec_dec (x) (i))) (('b"1")) return M (Z) then
          let new_count := Z.add (count) (1) in
          assert_exp' (Z.leb (new_count) n) "core/arithmetic.sail:85.28-85.29" >>= fun _ =>
          returnM (new_count)
        else returnM (count))
        : M (Z))))
    : M (Z).

Definition range_subset {n : Z}
(a_begin : mword n) (a_size : mword n) (b_begin : mword n) (b_size : mword n) (*n >=? 0*)
(*(0 <=? n) && (n <=? 64)*)
: bool :=
   let a_end := sub_vec ((add_vec (a_begin) (a_size))) (b_begin) in
   let b_end := sub_vec ((add_vec (b_begin) (b_size))) (b_begin) in
   let a_begin := sub_vec (a_begin) (b_begin) in
   andb ((zopz0zIzJ_u (a_begin) (b_end)))
     ((andb ((zopz0zIzJ_u (a_end) (b_end))) ((zopz0zIzJ_u (a_begin) (a_end))))).

Definition test_range_subset '(tt : unit) : M (unit) :=
   assert_exp (range_subset ((Ox"0")) ((Ox"0")) ((Ox"0")) ((Ox"0"))) "core/range_util.sail:27.41-27.42" >>
   assert_exp (range_subset ((Ox"1")) ((Ox"0")) ((Ox"1")) ((Ox"0"))) "core/range_util.sail:28.41-28.42" >>
   assert_exp (range_subset ((Ox"0")) ((Ox"0")) ((Ox"0")) ((Ox"1"))) "core/range_util.sail:29.41-29.42" >>
   assert_exp (range_subset ((Ox"1")) ((Ox"0")) ((Ox"0")) ((Ox"1"))) "core/range_util.sail:30.41-30.42" >>
   assert_exp (range_subset ((Ox"8")) ((Ox"C")) ((Ox"8")) ((Ox"C"))) "core/range_util.sail:31.41-31.42" >>
   assert_exp (not ((range_subset ((Ox"8")) ((Ox"C")) ((Ox"9")) ((Ox"C"))))) "core/range_util.sail:32.46-32.47" >>
   assert_exp (not ((range_subset ((Ox"8")) ((Ox"C")) ((Ox"8")) ((Ox"B"))))) "core/range_util.sail:33.46-33.47" >>
   assert_exp (not ((range_subset ((Ox"3E")) ((Ox"E0")) ((Ox"C1")) ((Ox"9F"))))) "core/range_util.sail:34.50-34.51" >>
   (assert_exp (not ((range_subset ((Ox"C1")) ((Ox"9F")) ((Ox"3E")) ((Ox"E0"))))) "core/range_util.sail:35.50-35.51")
    : M (unit).

Definition range_subset_equals
(a_begin : mword 8) (a_size : mword 8) (b_begin : mword 8) (b_size : mword 8)
: bool :=
   zopz0zJzJzK
     ((andb ((range_subset (a_begin) (a_size) (b_begin) (b_size)))
         ((range_subset (b_begin) (b_size) (a_begin) (a_size)))))
     ((andb ((eq_vec (a_begin) (b_begin))) ((eq_vec (a_size) (b_size))))).

Definition range_subset_precise
(a_begin : mword 8) (a_size : mword 8) (b_begin : mword 8) (b_size : mword 8) (index : mword 8)
: bool :=
   let index_in_a := zopz0zI_u ((sub_vec (index) (a_begin))) (a_size) in
   let index_in_b := zopz0zI_u ((sub_vec (index) (b_begin))) (b_size) in
   let is_subset := range_subset (a_begin) (a_size) (b_begin) (b_size) in
   andb ((zopz0zJzJzK ((andb (is_subset) (index_in_a))) (index_in_b)))
     ((zopz0zJzJzK ((andb (index_in_a) ((not (index_in_b))))) ((not (is_subset))))).

Definition float_class_onehot_bits_forwards (arg_ : float_class) : mword 10 :=
   match arg_ with
   | float_class_negative_inf => ('b"0000000001")
   | float_class_negative_normal => ('b"0000000010")
   | float_class_negative_subnormal => ('b"0000000100")
   | float_class_negative_zero => ('b"0000001000")
   | float_class_positive_zero => ('b"0000010000")
   | float_class_positive_subnormal => ('b"0000100000")
   | float_class_positive_normal => ('b"0001000000")
   | float_class_positive_inf => ('b"0010000000")
   | float_class_snan => ('b"0100000000")
   | float_class_qnan => ('b"1000000000")
   end.

Definition float_class_onehot_bits_backwards (arg_ : mword 10) : M (float_class) :=
   let p0_ := arg_ in
   (if eq_vec (p0_) (('b"0000000001")) then returnM (float_class_negative_inf)
    else if eq_vec (p0_) (('b"0000000010")) then returnM (float_class_negative_normal)
    else if eq_vec (p0_) (('b"0000000100")) then returnM (float_class_negative_subnormal)
    else if eq_vec (p0_) (('b"0000001000")) then returnM (float_class_negative_zero)
    else if eq_vec (p0_) (('b"0000010000")) then returnM (float_class_positive_zero)
    else if eq_vec (p0_) (('b"0000100000")) then returnM (float_class_positive_subnormal)
    else if eq_vec (p0_) (('b"0001000000")) then returnM (float_class_positive_normal)
    else if eq_vec (p0_) (('b"0010000000")) then returnM (float_class_positive_inf)
    else if eq_vec (p0_) (('b"0100000000")) then returnM (float_class_snan)
    else if eq_vec (p0_) (('b"1000000000")) then returnM (float_class_qnan)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (float_class).

Definition float_class_onehot_bits_forwards_matches (arg_ : float_class) : bool :=
   match arg_ with
   | float_class_negative_inf => true
   | float_class_negative_normal => true
   | float_class_negative_subnormal => true
   | float_class_negative_zero => true
   | float_class_positive_zero => true
   | float_class_positive_subnormal => true
   | float_class_positive_normal => true
   | float_class_positive_inf => true
   | float_class_snan => true
   | float_class_qnan => true
   end.

Definition float_class_onehot_bits_backwards_matches (arg_ : mword 10) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"0000000001")) then true
   else if eq_vec (p0_) (('b"0000000010")) then true
   else if eq_vec (p0_) (('b"0000000100")) then true
   else if eq_vec (p0_) (('b"0000001000")) then true
   else if eq_vec (p0_) (('b"0000010000")) then true
   else if eq_vec (p0_) (('b"0000100000")) then true
   else if eq_vec (p0_) (('b"0001000000")) then true
   else if eq_vec (p0_) (('b"0010000000")) then true
   else if eq_vec (p0_) (('b"0100000000")) then true
   else if eq_vec (p0_) (('b"1000000000")) then true
   else false.

Definition float_in_one_broad_class (f : mword 16) : bool :=
   Z.eqb
