Definition fence_bits_forwards (arg_ : mword 4) : string :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"0000")) then "0"
   else
     let i : bits 1 := subrange_vec_dec (p0_) (3) (3) in
     let w : bits 1 := subrange_vec_dec (p0_) (0) (0) in
     let r : bits 1 := subrange_vec_dec (p0_) (1) (1) in
     let o : bits 1 := subrange_vec_dec (p0_) (2) (2) in
     let i : bits 1 := subrange_vec_dec (p0_) (3) (3) in
     String.append ((bit_maybe_i_forwards (i)))
       ((String.append ((bit_maybe_o_forwards (o)))
           ((String.append ((bit_maybe_r_forwards (r)))
               ((String.append ((bit_maybe_w_forwards (w))) (""))))))).

