Definition assembly_forwards (arg_ : instruction) : M (string) :=
   match arg_ with
   | ZICBOP (cbop, rs1, offset) =>
      (hex_bits_12_forwards (offset)) >>= fun (w__0 : string) =>
      (reg_name_forwards (rs1)) >>= fun (w__1 : string) =>
      returnM ((String.append ((prefetch_mnemonic_forwards (cbop)))
                  ((String.append ((spc_forwards (tt)))
                      ((String.append (w__0)
                          ((String.append ("(")
                              ((String.append ((opt_spc_forwards (tt)))
                                  ((String.append (w__1)
                                      ((String.append ((opt_spc_forwards (tt)))
                                          ((String.append (")") ("")))))))))))))))))
   | NTL op => returnM ((String.append ("ntl.") ((String.append ((ntl_name_forwards (op))) ("")))))
   | C_NTL op =>
      returnM ((String.append ("c.ntl.") ((String.append ((ntl_name_forwards (op))) ("")))))
   | PAUSE tt => returnM ("pause")
   | LPAD lpl =>
      (hex_bits_20_forwards (lpl)) >>= fun (w__2 : string) =>
      returnM ((String.append ("lpad")
                  ((String.append ((spc_forwards (tt))) ((String.append (w__2) ("")))))))
   | UTYPE (imm, rd, op) =>
      (reg_name_forwards (rd)) >>= fun (w__3 : string) =>
      (hex_bits_signed_20_forwards (imm)) >>= fun (w__4 : string) =>
      returnM ((String.append ((utype_mnemonic_forwards (op)))
                  ((String.append ((spc_forwards (tt)))
                      ((String.append (w__3)
                          ((String.append ((sep_forwards (tt))) ((String.append (w__4) ("")))))))))))
   | JAL (imm, rd) =>
      (reg_name_forwards (rd)) >>= fun (w__5 : string) =>
      (hex_bits_signed_21_forwards (imm)) >>= fun (w__6 : string) =>
      returnM ((String.append ("jal")
                  ((String.append ((spc_forwards (tt)))
                      ((String.append (w__5)
                          ((String.append ((sep_forwards (tt))) ((String.append (w__6) ("")))))))))))
   | JALR (imm, rs1, rd) =>
      (reg_name_forwards (rd)) >>= fun (w__7 : string) =>
      (hex_bits_signed_12_forwards (imm)) >>= fun (w__8 : string) =>
      (reg_name_forwards (rs1)) >>= fun (w__9 : string) =>
      returnM ((String.append ("jalr")
                  ((String.append ((spc_forwards (tt)))
                      ((String.append (w__7)
                          ((String.append ((sep_forwards (tt)))
                              ((String.append (w__8)
                                  ((String.append ("(")
                                      ((String.append (w__9) ((String.append (")") ("")))))))))))))))))
   | BTYPE (imm, rs2, rs1, op) =>
