Definition assembly_forwards_matches (arg_ : instruction) : bool :=
   match arg_ with
   | ZICBOP (cbop, rs1, offset) => true
   | NTL op => true
   | C_NTL op => true
   | PAUSE tt => true
   | LPAD lpl => true
   | UTYPE (imm, rd, op) => true
   | JAL (imm, rd) => true
   | JALR (imm, rs1, rd) => true
   | BTYPE (imm, rs2, rs1, op) => true
   | ITYPE (imm, rs1, rd, op) => true
   | SHIFTIOP (shamt, rs1, rd, op) => true
   | RTYPE (rs2, rs1, rd, op) => true
   | LOAD (imm, rs1, rd, is_unsigned, width) => true
   | STORE (imm, rs2, rs1, width) => true
   | ADDIW (imm, rs1, rd) => true
   | RTYPEW (rs2, rs1, rd, op) => true
   | SHIFTIWOP (shamt, rs1, rd, op) => true
   | FENCE_TSO tt => true
   | FENCE (p0_, pred, succ, rs, rd) =>
      if andb ((andb ((generic_eq (rs) (zreg))) ((generic_eq (rd) (zreg)))))
           ((eq_vec (p0_) (('b"0000")))) then
        true
      else false
   | ECALL tt => true
   | MRET tt => true
   | SRET tt => true
   | EBREAK tt => true
   | WFI tt => true
   | SFENCE_VMA (rs1, rs2) => true
   | AMO (op, aq, rl, rs2, rs1, width, rd) => true
   | LOADRES (aq, rl, rs1, width, rd) => true
   | STORECON (aq, rl, rs2, rs1, width, rd) => true
   | MUL (rs2, rs1, rd, mul_op) => true
   | DIV (rs2, rs1, rd, is_unsigned) => true
   | REM (rs2, rs1, rd, is_unsigned) => true
   | MULW (rs2, rs1, rd) => true
   | DIVW (rs2, rs1, rd, is_unsigned) => true
   | REMW (rs2, rs1, rd, is_unsigned) => true
   | SLLIUW (shamt, rs1, rd) => true
   | ZBA_RTYPEUW (rs2, rs1, rd, shamt) => true
   | ZBA_RTYPE (rs2, rs1, rd, shamt) => true
   | RORIW (shamt, rs1, rd) => true
   | RORI (shamt, rs1, rd) => true
   | ZBB_RTYPEW (rs2, rs1, rd, op) => true
   | ZBB_RTYPE (rs2, rs1, rd, op) => true
   | ZBB_EXTOP (rs1, rd, op) => true
   | REV8 (rs1, rd) => true
   | ORCB (rs1, rd) => true
   | CPOP (rs1, rd) => true
   | CPOPW (rs1, rd) => true
   | CLZ (rs1, rd) => true
   | CLZW (rs1, rd) => true
   | CTZ (rs1, rd) => true
   | CTZW (rs1, rd) => true
   | CLMUL (rs2, rs1, rd) => true
   | CLMULH (rs2, rs1, rd) => true
   | CLMULR (rs2, rs1, rd) => true
   | ZBS_IOP (shamt, rs1, rd, op) => true
   | ZBS_RTYPE (rs2, rs1, rd, op) => true
   | C_NOP p0_ =>
      if eq_vec (p0_) (('b"000000")) then true
      else if neq_vec (p0_) ((zeros' (6))) then true
      else false
   | C_ADDI4SPN (rdc, nzimm) => if neq_vec (nzimm) (('b"00000000")) then true else false
   | C_LW (uimm, rsc, rdc) => true
   | C_LD (uimm, rsc, rdc) => true
   | C_SW (uimm, rsc1, rsc2) => true
   | C_SD (uimm, rsc1, rsc2) => true
   | C_ADDI (imm, rsd) => if generic_neq (rsd) (zreg) then true else false
   | C_JAL imm => if Z.eqb (xlen) (32) then true else false
   | C_ADDIW (imm, rsd) => true
   | C_LI (imm, rd) => true
   | C_ADDI16SP imm => if neq_vec (imm) (('b"000000")) then true else false
   | C_LUI (imm, rd) =>
      if andb ((generic_neq (rd) (sp))) ((neq_vec (imm) (('b"000000")))) then true else false
   | C_SRLI (shamt, rsd) => true
   | C_SRAI (shamt, rsd) => true
   | C_ANDI (imm, rsd) => true
   | C_SUB (rsd, rs2) => true
   | C_XOR (rsd, rs2) => true
   | C_OR (rsd, rs2) => true
   | C_AND (rsd, rs2) => true
   | C_SUBW (rsd, rs2) => true
   | C_ADDW (rsd, rs2) => true
   | C_J imm => true
   | C_BEQZ (imm, rs) => true
   | C_BNEZ (imm, rs) => true
   | C_SLLI (shamt, rsd) => true
   | C_LWSP (uimm, rd) => if generic_neq (rd) (zreg) then true else false
   | C_LDSP (uimm, rd) =>
      if andb ((generic_neq (rd) (zreg))) ((Z.eqb (xlen) (64))) then true else false
   | C_SWSP (uimm, rs2) => true
   | C_SDSP (uimm, rs2) => true
   | C_JR rs1 => if generic_neq (rs1) (zreg) then true else false
   | C_JALR rs1 => if generic_neq (rs1) (zreg) then true else false
   | C_MV (rd, rs2) => if generic_neq (rs2) (zreg) then true else false
   | C_EBREAK tt => true
   | C_ADD (rsd, rs2) => if generic_neq (rs2) (zreg) then true else false
   | C_LBU (uimm, rdc, rsc1) => true
   | C_LHU (uimm, rdc, rsc1) => true
   | C_LH (uimm, rdc, rsc1) => true
   | C_SB (uimm, rsc1, rsc2) => true
   | C_SH (uimm, rsc1, rsc2) => true
   | C_ZEXT_B rsdc => true
   | C_SEXT_B rsdc => true
   | C_ZEXT_H rsdc => true
   | C_SEXT_H rsdc => true
   | C_ZEXT_W rsdc => true
   | C_NOT rsdc => true
   | C_MUL (rsdc, rsc2) => true
   | CSRImm (csr, imm, rd, op) => true
   | CSRReg (csr, rs1, rd, op) => true
   | SINVAL_VMA (rs1, rs2) => true
   | SFENCE_W_INVAL tt => true
   | SFENCE_INVAL_IR tt => true
   | WRS WRS_STO => true
   | WRS WRS_NTO => true
   | SSPUSH rs2 => true
   | C_SSPUSH tt => true
   | SSPOPCHK rs1 => true
   | C_SSPOPCHK tt => true
   | SSRDP rd => true
   | SSAMOSWAP (aq, rl, rs2, rs1, width, rd) =>
      if orb ((Z.eqb (width) (4))) ((Z.eqb (width) (8))) then true else false
   | ZICOND_RTYPE (rs2, rs1, rd, op) => true
   | ZICBOM (cbop, rs1) => true
   | ZICBOZ rs1 => true
   | FENCEI (p0_, rs, rd) =>
      if andb ((andb ((generic_eq (rs) (zreg))) ((generic_eq (rd) (zreg)))))
           ((eq_vec (p0_) ((Ox"000")))) then
        true
      else false
   | ZIMOP_MOP_R (mop, rs1, rd) => true
   | ZIMOP_MOP_RR (mop, rs2, rs1, rd) => true
   | ZCMOP mop => true
   | ILLEGAL s => true
   | C_ILLEGAL s => true
   end.

