Definition instruction_to_str (insn : instruction) : M (string) :=
   (if assembly_forwards_matches (insn) return M (string) then
      (assembly_forwards (insn))
       : M (string)
    else
      (encdec_forwards (insn)) >>= fun (w__1 : mword 32) =>
      returnM ((String.append (".insn ") ((string_of_bits (w__1))))))
    : M (string).

Definition interruptType_to_str (i : InterruptType) : string :=
   match i with
   | I_Reserved_0 => "reserved-interrupt-0"
   | I_S_Software => "supervisor-software-interrupt"
   | I_VS_Software => "virtual-supervisor-software-interrupt"
   | I_M_Software => "machine-software-interrupt"
   | I_Reserved_4 => "reserved-interrupt-4"
   | I_S_Timer => "supervisor-timer-interrupt"
   | I_VS_Timer => "virtual-supervisor-timer-interrupt"
   | I_M_Timer => "machine-timer-interrupt"
   | I_Reserved_8 => "reserved-interrupt-8"
   | I_S_External => "supervisor-external-interrupt"
   | I_VS_External => "virtual-supervisor-external-interrupt"
   | I_M_External => "machine-external-interrupt"
   | I_SG_External => "supervisor guest-external-interrupt"
   | I_COF => "counter-overflow interrupt"
   end.

Definition memory_region_type_str_backwards (arg_ : string) : M (MemoryRegionType) :=
   let p0_ := arg_ in
   (if generic_eq (p0_) ("main memory") then returnM (MainMemory)
    else if generic_eq (p0_) ("IO memory") then returnM (IOMemory)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (MemoryRegionType).

Definition memory_region_type_str_forwards (arg_ : MemoryRegionType) : string :=
   match arg_ with | MainMemory => "main memory" | IOMemory => "IO memory" end.

Definition optional_misaligned_exception_str (opt_e : option misaligned_exception) : string :=
   match opt_e with | None => "NoFault" | Some e => misaligned_exception_str_forwards (e) end.

Definition pma_misaligned_to_str (m : PMAMisalignedExceptions) : string :=
   String.append ("misaligned-load-store:")
     ((String.append ((optional_misaligned_exception_str (m.(PMAMisalignedExceptions_load_store))))
         ((String.append (" misaligned-amo:")
             ((String.append ((misaligned_exception_str_forwards (m.(PMAMisalignedExceptions_amo))))
                 ((String.append (" misaligned-vector:")
                     ((optional_misaligned_exception_str (m.(PMAMisalignedExceptions_vector)))))))))))).

Definition reservability_str_forwards (arg_ : Reservability) : string :=
   match arg_ with
   | RsrvNone => "RsrvNone"
   | RsrvNonEventual => "RsrvNonEventual"
   | RsrvEventual => "RsrvEventual"
   end.

Definition pma_attributes_to_str (attr : PMA) : string :=
   String.append
     (match attr.(PMA_mem_type) with | MainMemory => " main-memory" | IOMemory => " io-memory" end)
     ((String.append ((if attr.(PMA_cacheable) then " cacheable" else ""))
         ((String.append ((if attr.(PMA_coherent) then " coherent" else ""))
             ((String.append ((if attr.(PMA_executable) then " executable" else ""))
                 ((String.append ((if attr.(PMA_readable) then " readable" else ""))
                     ((String.append ((if attr.(PMA_writable) then " writable" else ""))
                         ((String.append
                             ((if attr.(PMA_read_idempotent) then " read-idempotent"
                               else ""))
                             ((String.append
                                 ((if attr.(PMA_write_idempotent) then " write-idempotent"
                                   else ""))
                                 ((String.append (" ")
                                     ((String.append
                                         ((pma_misaligned_to_str (attr.(PMA_misaligned_exceptions))))
                                         ((String.append (" ")
                                             ((String.append
                                                 ((atomic_support_str_forwards
                                                     (attr.(PMA_atomic_support))))
                                                 ((String.append (" ")
                                                     ((String.append
                                                         ((reservability_str_forwards
                                                             (attr.(PMA_reservability))))
                                                         ((String.append
                                                             ((if attr.(PMA_supports_cbo_zero) then
                                                                 " supports-cbo-zero"
                                                               else ""))
                                                             ((String.append
                                                                 ((if attr.(PMA_supports_pte_read)
                                                                   then
                                                                     " supports-pte-read"
                                                                   else ""))
                                                                 ((String.append
                                                                     ((if attr.(PMA_supports_pte_write)
                                                                       then
                                                                         " supports-pte-write"
                                                                       else "")) (" "))))))))))))))))))))))))))))))))).

Definition pma_region_to_str (region : PMA_Region) : string :=
   String.append ("base: ")
     ((String.append ((string_of_bits (region.(PMA_Region_base))))
         ((String.append (" size: ")
             ((String.append ((string_of_bits (region.(PMA_Region_size))))
                 ((pma_attributes_to_str (region.(PMA_Region_attributes)))))))))).

Definition privLevel_to_str (p : Privilege) : M (string) :=
   match p with
   | User => returnM ("U")
   | VirtualUser => returnM ("VU")
   | Supervisor =>
      (currentlyEnabled (Ext_H)) >>= fun (w__0 : bool) =>
      let w__1 : string := if w__0 then "HS" else "S" in
      returnM (w__1)
   | VirtualSupervisor => returnM ("VS")
   | Machine => returnM ("M")
   end
    : M (string).

Definition ptw_error_to_str (e : PTW_Error) : string :=
   match e with
   | PTW_Invalid_Addr tt => "invalid-source-addr"
   | PTW_No_Access tt => "mem-access-error"
   | PTW_Invalid_PTE tt => "invalid-pte"
   | PTW_No_Permission tt => "no-permission"
   | PTW_Misaligned tt => "misaligned-superpage"
   | PTW_PTE_Needs_Update tt => "pte-update-needed"
   | PTW_Ext_Error _ => "extension-error"
   end.

Definition reservability_str_backwards (arg_ : string) : M (Reservability) :=
   let p0_ := arg_ in
   (if generic_eq (p0_) ("RsrvNone") then returnM (RsrvNone)
    else if generic_eq (p0_) ("RsrvNonEventual") then returnM (RsrvNonEventual)
    else if generic_eq (p0_) ("RsrvEventual") then returnM (RsrvEventual)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (Reservability).

Definition trapCause_to_str (t : TrapCause) : string :=
   match t with
   | Interrupt i => String.append ("int#") ((interruptType_to_str (i)))
   | Exception e => String.append ("exc#") ((exceptionType_to_str (e)))
   end.

Definition wait_name_backwards (arg_ : string) : M (WaitReason) :=
   let p0_ := arg_ in
   (if generic_eq (p0_) ("WAIT-WFI") then returnM (WAIT_WFI)
    else if generic_eq (p0_) ("WAIT-WRS-STO") then returnM (WAIT_WRS_STO)
    else if generic_eq (p0_) ("WAIT-WRS-NTO") then returnM (WAIT_WRS_NTO)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (WaitReason).

Definition wait_name_forwards (arg_ : WaitReason) : string :=
   match arg_ with
   | WAIT_WFI => "WAIT-WFI"
   | WAIT_WRS_STO => "WAIT-WRS-STO"
