      (internal_error ("core/mem_type_utils.sail") (32)
         ((String.append ("Invalid payloads (")
             ((String.append ((mem_payload_name_forwards (rp)))
                 ((String.append (", ")
                     ((String.append ((mem_payload_str_forwards (wp))) (") for Atomic."))))))))))
       : M (ExceptionType)
