Definition rX_bits '((Regidx i) : regidx) : M (mword 64) :=
   (rX ((Regno ((uint (i))))))  : M (mword 64).

Definition wX_bits '((Regidx i) : regidx) (data : mword 64) : M (unit) :=
   (wX ((Regno ((uint (i))))) (data))  : M (unit).

Definition rX_pair_bits (i : regidx) : M (mword (64 * 2)) :=
   (if generic_neq (i) (zreg) return M (mword (64 * 2)) then
      (rX_bits ((regidx_offset_range (i) (1)))) >>= fun (w__0 : mword 64) =>
      (rX_bits (i)) >>= fun (w__1 : mword 64) => returnM ((concat_vec (w__0) (w__1)))
    else returnM ((zeros' ((Z.mul (64) (2))))))
    : M (mword (64 * 2)).

Definition wX_pair_bits (i : regidx) (data : mword (64 * 2)) : M (unit) :=
   (if generic_neq (i) (zreg) return M (unit) then
      (wX_bits (i) ((subrange_vec_dec (data) ((Z.sub (xlen) (1))) (0)))) >>
      (wX_bits ((regidx_offset_range (i) (1)))
         ((subrange_vec_dec (data) ((Z.sub ((Z.mul (xlen) (2))) (1))) (xlen))))
       : M (unit)
    else returnM (tt))
    : M (unit).

