Definition ext_veto_disable_C '(tt : unit) : bool := false.

Definition legalize_misa (m : mword 64) (v : mword 64) : M (mword 64) :=
   let v := Mk_Misa (v) in
   (or_boolM (returnM ((not (sys_enable_writable_misa))))
      ((and_boolM (returnM (((eq_vec ((_get_Misa_C (v))) (('b"0")))  : bool)))
          ((or_boolM
              (((read_reg nextPC)  : M (mword 64)) >>= fun (w__0 : mword 64) =>
               returnM (((eq_vec ((access_vec_dec (w__0) (1))) (('b"1")))  : bool)))
              (returnM (((ext_veto_disable_C (tt))  : bool))))
           : M (bool)))
       : M (bool))) >>= fun w__3 =>
   (if w__3 then returnM (m)
    else
      (hartSupports (Ext_A)) >>= fun (w__4 : bool) =>
      let w__5 : mword 1 := if w__4 then _get_Misa_A (v) else ('b"0") in
      (hartSupports (Ext_B)) >>= fun (w__6 : bool) =>
      let w__7 : mword 1 := if w__6 then _get_Misa_B (v) else ('b"0") in
      (hartSupports (Ext_C)) >>= fun (w__8 : bool) =>
      let w__9 : mword 1 := if w__8 then _get_Misa_C (v) else ('b"0") in
      (and_boolM ((hartSupports (Ext_D))  : M (bool))
         (returnM (((eq_vec ((_get_Misa_F (v))) (('b"1")))  : bool)))) >>= fun (w__11 : bool) =>
      let w__12 : mword 1 := if w__11 then _get_Misa_D (v) else ('b"0") in
      (hartSupports (Ext_F)) >>= fun (w__13 : bool) =>
      let w__14 : mword 1 := if w__13 then _get_Misa_F (v) else ('b"0") in
      (hartSupports (Ext_H)) >>= fun (w__15 : bool) =>
      let w__16 : mword 1 := if w__15 then _get_Misa_H (v) else ('b"0") in
      (hartSupports (Ext_M)) >>= fun (w__17 : bool) =>
      let w__18 : mword 1 := if w__17 then _get_Misa_M (v) else ('b"0") in
      (and_boolM ((hartSupports (Ext_S))  : M (bool))
         (returnM (((eq_vec ((_get_Misa_U (v))) (('b"1")))  : bool)))) >>= fun (w__20 : bool) =>
      let w__21 : mword 1 := if w__20 then _get_Misa_S (v) else ('b"0") in
      (hartSupports (Ext_U)) >>= fun (w__22 : bool) =>
      let w__23 : mword 1 := if w__22 then _get_Misa_U (v) else ('b"0") in
      (and_boolM ((hartSupports (Ext_V))  : M (bool))
         (returnM (((andb ((eq_vec ((_get_Misa_F (v))) (('b"1"))))
                       ((eq_vec ((_get_Misa_D (v))) (('b"1")))))
           : bool)))) >>= fun (w__25 : bool) =>
      let w__26 : mword 1 := if w__25 then _get_Misa_V (v) else ('b"0") in
      returnM ((_update_Misa_V
                  ((_update_Misa_U
                      ((_update_Misa_S
                          ((_update_Misa_M
                              ((_update_Misa_E
                                  ((_update_Misa_I
                                      ((_update_Misa_H
                                          ((_update_Misa_F
                                              ((_update_Misa_D
                                                  ((_update_Misa_C
                                                      ((_update_Misa_B ((_update_Misa_A (m) (w__5)))
                                                          (w__7))) (w__9))) (w__12))) (w__14)))
                                          (w__16))) ((bool_to_bit ((not (base_E_enabled)))))))
                                  ((bool_to_bit (base_E_enabled))))) (w__18))) (w__21))) (w__23)))
                  (w__26))))
    : M (mword 64).

Definition lowest_supported_privLevel '(tt : unit) : M (Privilege) :=
   (currentlyEnabled (Ext_U)) >>= fun (w__0 : bool) =>
