   returnM (w__1).

Definition have_nominal_privLevel (priv : mword 2) : M (bool) :=
   let p0_ := priv in
   (if eq_vec (p0_) (('b"00")) return M (bool) then (currentlyEnabled (Ext_U))  : M (bool)
    else if eq_vec (p0_) (('b"01")) return M (bool) then (currentlyEnabled (Ext_S))  : M (bool)
    else returnM ((if eq_vec (p0_) (('b"10")) then false else true)))
    : M (bool).

