Definition undefined_FeatureEnabledResult '(tt : unit) : M (FeatureEnabledResult) :=
   (internal_pick ([FEATURE_ENABLED; FEATURE_ILLEGAL; FEATURE_VIRTUAL]))  : M (FeatureEnabledResult).

Definition feature_enabled_for_priv
(p : Privilege) (machine_enable_bit : mword 1) (supervisor_enable_bit : mword 1)
(hypervisor_enable_bit : mword 1)
: M (FeatureEnabledResult) :=
   match p with
   | Machine => returnM (FEATURE_ENABLED)
   | Supervisor =>
      returnM ((if eq_vec (machine_enable_bit) (('b"1")) then FEATURE_ENABLED else FEATURE_ILLEGAL))
   | User =>
      (and_boolM (returnM (((eq_vec (machine_enable_bit) (('b"1")))  : bool)))
         ((or_boolM
             ((currentlyEnabled (Ext_S)) >>= fun (w__0 : bool) => returnM (((not (w__0))  : bool)))
             (returnM (((eq_vec (supervisor_enable_bit) (('b"1")))  : bool))))
          : M (bool))) >>= fun (w__2 : bool) =>
      let w__3 : FeatureEnabledResult := if w__2 then FEATURE_ENABLED else FEATURE_ILLEGAL in
      returnM (w__3)
   | VirtualSupervisor =>
      returnM ((if eq_vec (machine_enable_bit) (('b"0")) then FEATURE_ILLEGAL
                else if eq_vec (hypervisor_enable_bit) (('b"0")) then FEATURE_VIRTUAL
                else FEATURE_ENABLED))
   | VirtualUser =>
      returnM ((if eq_vec (machine_enable_bit) (('b"0")) then FEATURE_ILLEGAL
                else if orb ((eq_vec (hypervisor_enable_bit) (('b"0"))))
                          ((eq_vec (supervisor_enable_bit) (('b"0")))) then
                  FEATURE_VIRTUAL
                else FEATURE_ENABLED))
   end
    : M (FeatureEnabledResult).

Definition feature_enabled_for_priv_bool (p : Privilege) (m : mword 1) (s : mword 1) (h : mword 1)
: M (bool) :=
   (feature_enabled_for_priv (p) (m) (s) (h)) >>= fun (w__0 : FeatureEnabledResult) =>
   returnM ((generic_eq (w__0) (FEATURE_ENABLED))).

