: M (bool) :=
   ((read_reg mcounteren)  : M (mword 32)) >>= fun (w__0 : mword 32) =>
   ((read_reg scounteren)  : M (mword 32)) >>= fun (w__1 : mword 32) =>
   (feature_enabled_for_priv_bool (priv) ((access_vec_dec (w__0) (index)))
      ((access_vec_dec (w__1) (index))) (('b"0")))
    : M (bool).

