Definition prepare_trap_vector (p : Privilege) (cause : mword 64) : M (mword 64) :=
   match p with
   | Machine => ((read_reg mtvec)  : M (mword 64))  : M (mword 64)
   | Supervisor => ((read_reg stvec)  : M (mword 64))  : M (mword 64)
   | User =>
      (internal_error ("exceptions/sys_exceptions.sail") (25) ("Invalid privilege level"))
       : M (mword 64)
   | VirtualUser =>
      (internal_error ("exceptions/sys_exceptions.sail") (26) ("Hypervisor extension not supported"))
       : M (mword 64)
   | VirtualSupervisor =>
      (internal_error ("exceptions/sys_exceptions.sail") (27) ("Hypervisor extension not supported"))
       : M (mword 64)
   end >>= fun (tvec : Mtvec) =>
   match tvec_addr (tvec) (cause) with
   | Some epc => returnM (epc)
   | None =>
      (internal_error ("exceptions/sys_exceptions.sail") (31) ("Invalid tvec mode"))  : M (mword 64)
   end
    : M (mword 64).

Definition get_xepc (p : Privilege) : M (mword 64) :=
   match p with
   | Machine =>
      ((read_reg mepc)  : M (mword 64)) >>= fun (w__0 : mword 64) =>
      (align_pc (w__0))
       : M (mword 64)
   | Supervisor =>
      ((read_reg sepc)  : M (mword 64)) >>= fun (w__2 : mword 64) =>
      (align_pc (w__2))
       : M (mword 64)
   | User =>
      (internal_error ("exceptions/sys_exceptions.sail") (45) ("Invalid privilege level"))
       : M (mword 64)
   | VirtualUser =>
      (internal_error ("exceptions/sys_exceptions.sail") (46) ("Hypervisor extension not supported"))
       : M (mword 64)
   | VirtualSupervisor =>
      (internal_error ("exceptions/sys_exceptions.sail") (47) ("Hypervisor extension not supported"))
       : M (mword 64)
   end
    : M (mword 64).

Definition set_xepc (p : Privilege) (value : mword 64) : M (mword 64) :=
   (legalize_xepc (value)) >>= fun target =>
   match p with
   | Machine => write_reg mepc target  : M (unit)
   | Supervisor => write_reg sepc target  : M (unit)
   | User =>
      (internal_error ("exceptions/sys_exceptions.sail") (55) ("Invalid privilege level"))
       : M (unit)
   | VirtualUser =>
      (internal_error ("exceptions/sys_exceptions.sail") (56) ("Hypervisor extension not supported"))
       : M (unit)
   | VirtualSupervisor =>
      (internal_error ("exceptions/sys_exceptions.sail") (57) ("Hypervisor extension not supported"))
       : M (unit)
   end >>
   returnM (target).

Definition prepare_xret_target (p : Privilege) : M (mword 64) := (get_xepc (p))  : M (mword 64).

