Definition pmpAddrMatchType_encdec_forwards (arg_ : PmpAddrMatchType) : mword 2 :=
   match arg_ with | OFF => ('b"00") | TOR => ('b"01") | NA4 => ('b"10") | NAPOT => ('b"11") end.

Definition pmpAddrMatchType_encdec_backwards (arg_ : mword 2) : PmpAddrMatchType :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"00")) then OFF
   else if eq_vec (p0_) (('b"01")) then TOR
   else if eq_vec (p0_) (('b"10")) then NA4
   else NAPOT.

Definition pmpAddrMatchType_encdec_forwards_matches (arg_ : PmpAddrMatchType) : bool :=
   match arg_ with | OFF => true | TOR => true | NA4 => true | NAPOT => true end.

Definition pmpAddrMatchType_encdec_backwards_matches (arg_ : mword 2) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"00")) then true
   else if eq_vec (p0_) (('b"01")) then true
   else if eq_vec (p0_) (('b"10")) then true
   else if eq_vec (p0_) (('b"11")) then true
   else false.

