Definition pmpWriteCfg (cfg : mword 8) (v : mword 8) : M (mword 8) :=
   (if pmpLocked (cfg) then returnM (cfg)
    else
      let cfg := Mk_Pmpcfg_ent ((and_vec (v) ((Ox"9F")))) in
      (if andb ((eq_vec ((_get_Pmpcfg_ent_W (cfg))) (('b"1"))))
            ((eq_vec ((_get_Pmpcfg_ent_R (cfg))) (('b"0"))))
         return
