         match pmp_write_only_reserved_behavior with
         | PMP_Fatal => (reserved_behavior ("pmpcfg with R=0,W=1"))  : M (mword 8)
         | PMP_ClearPermissions =>
            returnM ((_update_Pmpcfg_ent_R
                        ((_update_Pmpcfg_ent_W ((_update_Pmpcfg_ent_X (cfg) (('b"0")))) (('b"0"))))
                        (('b"0"))))
