Definition pmpRangeMatch (begin : Z) (end_ : Z) (addr : Z) (width : Z) (*0 <=? begin*)
(*0 <=? end_*) (*0 <=? addr*) (*0 <=? width*)
: pmpAddrMatch :=
   if orb ((Z.leb ((Z.add (addr) (width))) (begin))) ((Z.leb (end_) (addr))) then PMP_NoMatch
   else if andb ((Z.leb (begin) (addr))) ((Z.leb ((Z.add (addr) (width))) (end_))) then PMP_Match
   else PMP_PartialMatch.

Definition pmpMatchAddr
'((Physaddr addr) : physaddr) (width : mword 64) (ent : mword 8) (pmpaddr : mword 64)
(prev_pmpaddr : mword 64)
: M (pmpAddrMatch) :=
   let addr := uint (addr) in
   let width := uint (width) in
   match pmpAddrMatchType_encdec_backwards ((_get_Pmpcfg_ent_A (ent))) with
   | OFF => returnM (PMP_NoMatch)
   | TOR =>
      returnM ((if zopz0zKzJ_u (prev_pmpaddr) (pmpaddr) then PMP_NoMatch
                else
                  pmpRangeMatch ((Z.mul ((uint (prev_pmpaddr))) (4)))
                    ((Z.mul ((uint (pmpaddr))) (4))) (addr) (width)))
   | NA4 =>
      assert_exp' (Z.ltb (sys_pmp_grain) (1)) "NA4 cannot be selected when PMP grain G >= 1." >>= fun _ =>
      let begin := Z.mul ((uint (pmpaddr))) (4) in
      returnM ((pmpRangeMatch (begin) ((Z.add (begin) (4))) (addr) (width)))
   | NAPOT =>
      let mask := xor_vec (pmpaddr) ((add_vec_int (pmpaddr) (1))) in
      let begin_words := uint ((and_vec (pmpaddr) ((not_vec (mask))))) in
      let end_words := Z.add ((Z.add (begin_words) ((uint (mask))))) (1) in
      returnM ((pmpRangeMatch ((Z.mul (begin_words) (4))) ((Z.mul (end_words) (4))) (addr) (width)))
   end
    : M (pmpAddrMatch).

Definition pmpCheck
(addr : physaddr) (width : Z) (access : MemoryAccessType mem_payload) (priv : Privilege)
(*(0 <? width) && (width <=? 4096)*)
: M (option ExceptionType) :=
   catch_early_return
     ((if Z.eqb (sys_pmp_count) (0) then returnR (option ExceptionType) (None)
       else
         let width : xlenbits := to_bits (64) (width) in
         (let '(loop_i_lower) := 0 in
         let '(loop_i_upper) := Z.sub (sys_pmp_count) (1) in
         (foreach_ZM_up loop_i_lower loop_i_upper 1 tt
           (fun i _ =>
             (if Z.gtb (i) (0) return MR (option ExceptionType) (mword 64) then
                liftR ((pmpReadAddrReg ((Z.sub (i) (1)))))
                 : MR (option ExceptionType) (mword 64)
