   (reg_deref (r_ref)) >>= fun r => write_reg_ref r_ref (_update_Vcsr_vxrm (r) (v))  : M (unit).

Definition _get_Vcsr_vxsat (v : mword 3) : mword 1 := subrange_vec_dec (v) (0) (0).

Definition _update_Vcsr_vxsat (v : mword 3) (x : mword 1) : mword 3 :=
   update_subrange_vec_dec (v) (0) (0) (x).

Definition _set_Vcsr_vxsat (r_ref : register_ref (mword 3)) (v : mword 1) : M (unit) :=
   (reg_deref (r_ref)) >>= fun r => write_reg_ref r_ref (_update_Vcsr_vxsat (r) (v))  : M (unit).

Definition set_vstart (value : mword 16) : M (unit) :=
   (dirty_v_context (tt)) >>
   write_reg vstart (zero_extend' (64) ((subrange_vec_dec (value) ((Z.sub (vlen_exp) (1))) (0)))) >>
   ((read_reg vstart)  : M (mword 64)) >>= fun (w__0 : mword 64) =>
   (csr_name_write_callback ("vstart") (w__0))
    : M (unit).

Definition write_vcsr (vxrm_val : mword 2) (vxsat_val : mword 1) : M (unit) :=
   ((read_reg vcsr)  : M (mword 3)) >>= fun (w__0 : mword 3) =>
   write_reg vcsr (update_subrange_vec_dec (w__0) (2) (1) (vxrm_val)) >>
   ((read_reg vcsr)  : M (mword 3)) >>= fun (w__1 : mword 3) =>
   write_reg vcsr (update_subrange_vec_dec (w__1) (0) (0) (vxsat_val)) >>
   (dirty_v_context (tt))
    : M (unit).

Definition max_index_eew_exp := 6  : Z.
#[export] Hint Unfold max_index_eew_exp : sail.
Definition get_num_elem (LMUL_pow : Z) (SEW : Z) (*(((- 3)) <=? LMUL_pow) && (LMUL_pow <=? 3)*)
(*member_Z_list SEW [8; 16; 32; 64]*)
: M (Z) :=
   assert_exp' (Z.geb (vlen) (SEW)) "extensions/V/vext_control.sail:40.20-40.21" >>= fun _ =>
   returnM ((Z.quot ((Z.mul ((pow2 ((Z.max (0) (LMUL_pow))))) (vlen))) (SEW))).

Definition read_single_element (EEW : Z) (index : Z) (vrid : vregidx) (*EEW >=? 0*)
(*member_Z_list EEW [8; 16; 32; 64]*) (*0 <=? index*)
: M (mword EEW) :=
   assert_exp' (Z.leb (EEW) (vlen)) "extensions/V/vext_control.sail:47.20-47.21" >>= fun _ =>
   let '(_) := (static_assert ((Z.eqb ((Z.rem (vlen) (EEW))) (0))))  : unit in
   let elem_per_reg := Z.quot (vlen) (EEW) in
   let reg_in_group := Z.quot (index) (elem_per_reg) in
   assert_exp' (Z.ltb (reg_in_group) (8)) "extensions/V/vext_control.sail:55.25-55.26" >>= fun _ =>
   let vrid := vregidx_offset_range (vrid) (reg_in_group) in
   let index := Z.rem (index) (elem_per_reg) in
   let offset := Z.mul (index) (EEW) in
   (rV_bits (vrid)) >>= fun (w__0 : mword (2 ^ 8)) =>
   returnM ((autocast (T := mword)
             (subrange_vec_dec (w__0) ((Z.sub ((Z.add (offset) (EEW))) (1))) (offset)))).

Definition read_vreg (num_elem : Z) (SEW : Z) (LMUL_pow : Z) (vrid : vregidx) (*num_elem >=? 0*)
(*SEW >=? 0*) (*(num_elem >=? 0) && member_Z_list SEW [8; 16; 32; 64]*)
: M (vec (mword SEW) num_elem) :=
   let vrid_val := uint ((vregidx_bits (vrid))) in
   let LMUL_pow_reg := if Z.ltb (LMUL_pow) (0) then 0 else LMUL_pow in
   let LMUL := pow2 (LMUL_pow_reg) in
   let vrid_end := Z.add (vrid_val) (LMUL) in
   assert_exp' (Z.leb (vrid_end) (32)) (String.append ("Invalid register group: group ")
                                          ((String.append ((dec_str (vrid_val)))
                                              ((String.append (" ends at ")
                                                  ((String.append ((dec_str (vrid_end)))
                                                      (" and overflows the largest register number (32).")))))))) >>= fun _ =>
   assert_exp' (Z.eqb ((Z.rem (vrid_val) (LMUL))) (0)) (String.append
                                                          ("Invalid register group: group ")
                                                          ((String.append ((dec_str (vrid_val)))
                                                              ((String.append
                                                                  (" is not a multiple of its EMUL ")
                                                                  ((String.append ((dec_str (LMUL)))
                                                                      (".")))))))) >>= fun _ =>
   let result' : vec (bits SEW) num_elem :=
     vector_init ((__id (num_elem))) ((zeros' ((__id (SEW))))) in
   (let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := Z.sub (num_elem) (1) in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 result'
     (fun i result' =>
       (read_single_element (SEW) (i) (vrid)) >>= fun (w__0 : mword SEW) =>
       let result' := (vec_update_dec (result') (i) (w__0))  : vec (mword SEW) num_elem in
       returnM (result'))))
    : M (vec (mword SEW) num_elem).

Definition write_single_element (EEW : Z) (index : Z) (vrid : vregidx) (value : mword EEW)
(*EEW >=? 0*) (*member_Z_list EEW [8; 16; 32; 64]*) (*0 <=? index*)
: M (unit) :=
   assert_exp' (Z.leb (EEW) (vlen)) "extensions/V/vext_control.sail:89.20-89.21" >>= fun _ =>
   let '(_) := (static_assert ((Z.eqb ((Z.rem (vlen) (EEW))) (0))))  : unit in
   let elem_per_reg := Z.quot (vlen) (EEW) in
   let reg_in_group := Z.quot (index) (elem_per_reg) in
   assert_exp' (Z.ltb (reg_in_group) (8)) "extensions/V/vext_control.sail:97.25-97.26" >>= fun _ =>
   let vrid := vregidx_offset_range (vrid) (reg_in_group) in
   let index := Z.rem (index) (elem_per_reg) in
   let offset := Z.mul (index) (EEW) in
   (rV_bits (vrid)) >>= fun (w__0 : mword (2 ^ 8)) =>
   (wV_bits (vrid)
      ((update_subrange_vec_dec (w__0) ((Z.sub ((Z.add (offset) (EEW))) (1))) (offset)
          ((autocast (T := mword) 
          value)))))
    : M (unit).

Definition write_vreg
(num_elem : Z) (SEW : Z) (LMUL_pow : Z) (vrid : vregidx) (vec' : vec (mword SEW) num_elem)
(*num_elem >=? 0*) (*SEW >=? 0*) (*(num_elem >=? 0) && member_Z_list SEW [8; 16; 32; 64]*)
(*(((- 3)) <=? LMUL_pow) && (LMUL_pow <=? 3)*)
: M (unit) :=
   let group_size := pow2 ((Z.max (LMUL_pow) (0))) in
   assert_exp' (Z.leb (SEW) (vlen)) "extensions/V/vext_control.sail:124.20-124.21" >>= fun _ =>
   let '(_) := (static_assert ((Z.eqb ((Z.rem (vlen) (SEW))) (0))))  : unit in
   let elem_per_reg := Z.quot (vlen) (SEW) in
   assert_exp' (orb ((Z.eqb (num_elem) ((Z.mul (group_size) (elem_per_reg)))))
                  ((Z.eqb (num_elem) ((Z.mul ((Z.mul (2) (group_size))) (elem_per_reg)))))) "extensions/V/vext_control.sail:139.90-139.91" >>= fun _ =>
   let '(loop_reg_in_group_lower) := 0 in
   let '(loop_reg_in_group_upper) := Z.sub (group_size) (1) in
   (foreach_ZM_up loop_reg_in_group_lower loop_reg_in_group_upper 1 tt
     (fun reg_in_group _ =>
       let reg_value : vlenbits := zeros' ((pow2 (8))) in
       let reg_value : mword (2 ^ 8) :=
         let '(loop_i_elem_lower) := 0 in
         let '(loop_i_elem_upper) := Z.sub (elem_per_reg) (1) in
         (foreach_Z_up loop_i_elem_lower loop_i_elem_upper 1 reg_value
           (fun i_elem reg_value =>
             update_subrange_vec_dec (reg_value)
               ((Z.sub ((Z.add ((Z.mul (i_elem) (SEW))) (SEW))) (1))) ((Z.mul (i_elem) (SEW)))
               ((autocast (T := mword)
                 (vec_access_dec (vec') ((Z.add ((Z.mul (reg_in_group) (elem_per_reg))) (i_elem)))))))) in
       (wV_bits ((vregidx_offset_range (vrid) (reg_in_group))) (reg_value))
        : M (unit))).

Definition read_vmask (num_elem : Z) (vm : mword 1) (vrid : vregidx) (*num_elem >=? 0*)
(*(0 <? num_elem) && (num_elem <=? (2 ^ 8))*)
: M (mword num_elem) :=
   (if eq_vec (vm) (('b"1")) then returnM ((ones ((__id (num_elem)))))
    else
      (rV_bits (vrid)) >>= fun (w__0 : mword (2 ^ 8)) =>
      returnM ((autocast (T := mword)
                (concat_vec ((ones ((Z.sub ((__id (num_elem))) (num_elem)))))
                   ((subrange_vec_dec (w__0) ((Z.sub (num_elem) (1))) (0)))))))
    : M (mword num_elem).

Definition read_vmask_carry (num_elem : Z) (vm : mword 1) (vrid : vregidx) (*num_elem >=? 0*)
(*(0 <? num_elem) && (num_elem <=? (2 ^ 8))*)
: M (mword num_elem) :=
   (if eq_vec (vm) (('b"1")) then returnM ((zeros' ((__id (num_elem)))))
    else
      (rV_bits (vrid)) >>= fun (w__0 : mword (2 ^ 8)) =>
      returnM ((autocast (T := mword)
                (concat_vec ((zeros' ((Z.sub ((__id (num_elem))) (num_elem)))))
                   ((subrange_vec_dec (w__0) ((Z.sub (num_elem) (1))) (0)))))))
    : M (mword num_elem).

Definition write_vmask (num_elem : Z) (vrid : vregidx) (v : mword num_elem) (*num_elem >=? 0*)
(*num_elem >? 0*)
: M (unit) :=
   assert_exp' (andb ((Z.ltb (0) (num_elem))) ((Z.leb (num_elem) (vlen)))) "extensions/V/vext_control.sail:164.40-164.41" >>= fun _ =>
   (rV_bits (vrid)) >>= fun (w__0 : mword (2 ^ 8)) =>
   (wV_bits (vrid)
      ((update_subrange_vec_dec (w__0) ((Z.sub (num_elem) (1))) (0) ((autocast (T := mword)  v)))))
    : M (unit).

Definition xt2 (x : mword 8) : mword 8 :=
   xor_vec ((shiftl (x) (1)))
     ((if bit_to_bool ((access_vec_dec (x) (7))) then (Ox"1B")
       else (Ox"00"))).

Definition xt3 (x : mword 8) : mword 8 := xor_vec (x) ((xt2 (x))).

Definition gfmul (x : mword 8) (y : mword 4) : mword 8 :=
   xor_vec ((if bit_to_bool ((access_vec_dec (y) (0))) then x else (Ox"00")))
     ((xor_vec ((if bit_to_bool ((access_vec_dec (y) (1))) then xt2 (x) else (Ox"00")))
         ((xor_vec ((if bit_to_bool ((access_vec_dec (y) (2))) then xt2 ((xt2 (x))) else (Ox"00")))
             ((if bit_to_bool ((access_vec_dec (y) (3))) then xt2 ((xt2 ((xt2 (x)))))
               else (Ox"00"))))))).

Definition aes_mixcolumn_byte_fwd (so : mword 8) : mword 32 :=
   concat_vec ((gfmul (so) ((Ox"3"))))
     ((concat_vec (so) ((concat_vec (so) ((gfmul (so) ((Ox"2")))))))).

Definition aes_mixcolumn_byte_inv (so : mword 8) : mword 32 :=
   concat_vec ((gfmul (so) ((Ox"B"))))
     ((concat_vec ((gfmul (so) ((Ox"D"))))
         ((concat_vec ((gfmul (so) ((Ox"9")))) ((gfmul (so) ((Ox"E")))))))).

Definition aes_mixcolumn_fwd (x : mword 32) : mword 32 :=
   let s0 : bits 8 := subrange_vec_dec (x) (7) (0) in
   let s1 : bits 8 := subrange_vec_dec (x) (15) (8) in
   let s2 : bits 8 := subrange_vec_dec (x) (23) (16) in
   let s3 : bits 8 := subrange_vec_dec (x) (31) (24) in
   let b0 : bits 8 := xor_vec ((xt2 (s0))) ((xor_vec ((xt3 (s1))) ((xor_vec (s2) (s3))))) in
   let b1 : bits 8 := xor_vec (s0) ((xor_vec ((xt2 (s1))) ((xor_vec ((xt3 (s2))) (s3))))) in
   let b2 : bits 8 := xor_vec (s0) ((xor_vec (s1) ((xor_vec ((xt2 (s2))) ((xt3 (s3))))))) in
   let b3 : bits 8 := xor_vec ((xt3 (s0))) ((xor_vec (s1) ((xor_vec (s2) ((xt2 (s3))))))) in
   concat_vec (b3) ((concat_vec (b2) ((concat_vec (b1) (b0))))).

Definition aes_mixcolumn_inv (x : mword 32) : mword 32 :=
   let s0 : bits 8 := subrange_vec_dec (x) (7) (0) in
   let s1 : bits 8 := subrange_vec_dec (x) (15) (8) in
   let s2 : bits 8 := subrange_vec_dec (x) (23) (16) in
   let s3 : bits 8 := subrange_vec_dec (x) (31) (24) in
   let b0 : bits 8 :=
     xor_vec ((gfmul (s0) ((Ox"E"))))
       ((xor_vec ((gfmul (s1) ((Ox"B"))))
           ((xor_vec ((gfmul (s2) ((Ox"D")))) ((gfmul (s3) ((Ox"9")))))))) in
   let b1 : bits 8 :=
     xor_vec ((gfmul (s0) ((Ox"9"))))
       ((xor_vec ((gfmul (s1) ((Ox"E"))))
           ((xor_vec ((gfmul (s2) ((Ox"B")))) ((gfmul (s3) ((Ox"D")))))))) in
   let b2 : bits 8 :=
     xor_vec ((gfmul (s0) ((Ox"D"))))
       ((xor_vec ((gfmul (s1) ((Ox"9"))))
           ((xor_vec ((gfmul (s2) ((Ox"E")))) ((gfmul (s3) ((Ox"B")))))))) in
   let b3 : bits 8 :=
     xor_vec ((gfmul (s0) ((Ox"B"))))
       ((xor_vec ((gfmul (s1) ((Ox"D"))))
           ((xor_vec ((gfmul (s2) ((Ox"9")))) ((gfmul (s3) ((Ox"E")))))))) in
   concat_vec (b3) ((concat_vec (b2) ((concat_vec (b1) (b0))))).

Definition aes_decode_rcon (r : mword 4) : M (mword 32) :=
   assert_exp (zopz0zI_u (r) ((Ox"A"))) "extensions/K/types_kext.sail:77.18-77.19" >>
   let p0_ := r in
   (if eq_vec (p0_) ((Ox"0")) then returnM ((Ox"00000001"))
    else if eq_vec (p0_) ((Ox"1")) then returnM ((Ox"00000002"))
    else if eq_vec (p0_) ((Ox"2")) then returnM ((Ox"00000004"))
    else if eq_vec (p0_) ((Ox"3")) then returnM ((Ox"00000008"))
    else if eq_vec (p0_) ((Ox"4")) then returnM ((Ox"00000010"))
    else if eq_vec (p0_) ((Ox"5")) then returnM ((Ox"00000020"))
    else if eq_vec (p0_) ((Ox"6")) then returnM ((Ox"00000040"))
    else if eq_vec (p0_) ((Ox"7")) then returnM ((Ox"00000080"))
    else if eq_vec (p0_) ((Ox"8")) then returnM ((Ox"0000001B"))
    else if eq_vec (p0_) ((Ox"9")) then returnM ((Ox"00000036"))
    else (internal_error ("extensions/K/types_kext.sail") (89) ("Unexpected AES r"))  : M (mword 32))
    : M (mword 32).

