Definition sbox_lookup (x : mword 8) (table : vec (mword 8) 256) : mword 8 :=
   vec_access_dec (table) ((Z.sub (255) ((uint (x))))).

Definition aes_sbox_fwd (x : mword 8) : mword 8 := sbox_lookup (x) (aes_sbox_fwd_table).

Definition aes_sbox_inv (x : mword 8) : mword 8 := sbox_lookup (x) (aes_sbox_inv_table).

Definition aes_subword_fwd (x : mword 32) : mword 32 :=
   concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (31) (24)))))
     ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (23) (16)))))
         ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (15) (8)))))
             ((aes_sbox_fwd ((subrange_vec_dec (x) (7) (0))))))))).

Definition aes_subword_inv (x : mword 32) : mword 32 :=
   concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (31) (24)))))
     ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (23) (16)))))
         ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (15) (8)))))
             ((aes_sbox_inv ((subrange_vec_dec (x) (7) (0))))))))).

Definition sm4_sbox (x : mword 8) : mword 8 := sbox_lookup (x) (sm4_sbox_table).

Definition aes_get_column (state : mword 128) (c : Z) (*(0 <=? c) && (c <=? 3)*) : mword 32 :=
   autocast (T := mword)
   (subrange_vec_dec (state) ((Z.add ((Z.mul (32) (c))) (31))) ((Z.mul (32) (c)))).

Definition aes_apply_fwd_sbox_to_each_byte (x : mword 64) : mword 64 :=
   concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (63) (56)))))
     ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (55) (48)))))
         ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (47) (40)))))
             ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (39) (32)))))
                 ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (31) (24)))))
                     ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (23) (16)))))
                         ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (15) (8)))))
                             ((aes_sbox_fwd ((subrange_vec_dec (x) (7) (0))))))))))))))))).

Definition aes_apply_inv_sbox_to_each_byte (x : mword 64) : mword 64 :=
   concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (63) (56)))))
     ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (55) (48)))))
         ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (47) (40)))))
             ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (39) (32)))))
                 ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (31) (24)))))
                     ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (23) (16)))))
                         ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (15) (8)))))
                             ((aes_sbox_inv ((subrange_vec_dec (x) (7) (0))))))))))))))))).

Definition getbyte (x : mword 64) (i : Z) (*(0 <=? i) && (i <=? 7)*) : mword 8 :=
   autocast (T := mword) (subrange_vec_dec (x) ((Z.add ((Z.mul (8) (i))) (7))) ((Z.mul (8) (i)))).

Definition aes_rv64_shiftrows_fwd (rs2 : mword 64) (rs1 : mword 64) : mword 64 :=
   concat_vec ((getbyte (rs1) (3)))
     ((concat_vec ((getbyte (rs2) (6)))
         ((concat_vec ((getbyte (rs2) (1)))
             ((concat_vec ((getbyte (rs1) (4)))
                 ((concat_vec ((getbyte (rs2) (7)))
                     ((concat_vec ((getbyte (rs2) (2)))
                         ((concat_vec ((getbyte (rs1) (5))) ((getbyte (rs1) (0))))))))))))))).

Definition aes_rv64_shiftrows_inv (rs2 : mword 64) (rs1 : mword 64) : mword 64 :=
   concat_vec ((getbyte (rs2) (3)))
     ((concat_vec ((getbyte (rs2) (6)))
         ((concat_vec ((getbyte (rs1) (1)))
             ((concat_vec ((getbyte (rs1) (4)))
                 ((concat_vec ((getbyte (rs1) (7)))
                     ((concat_vec ((getbyte (rs2) (2)))
                         ((concat_vec ((getbyte (rs2) (5))) ((getbyte (rs1) (0))))))))))))))).

Definition aes_shift_rows_fwd (x : mword 128) : mword 128 :=
   let ic3 : bits 32 := aes_get_column (x) (3) in
   let ic2 : bits 32 := aes_get_column (x) (2) in
   let ic1 : bits 32 := aes_get_column (x) (1) in
   let ic0 : bits 32 := aes_get_column (x) (0) in
   let oc0 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic3) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic2) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic1) (15) (8))) ((subrange_vec_dec (ic0) (7) (0))))))) in
   let oc1 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic0) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic3) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic2) (15) (8))) ((subrange_vec_dec (ic1) (7) (0))))))) in
   let oc2 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic1) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic0) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic3) (15) (8))) ((subrange_vec_dec (ic2) (7) (0))))))) in
   let oc3 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic2) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic1) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic0) (15) (8))) ((subrange_vec_dec (ic3) (7) (0))))))) in
   concat_vec (oc3) ((concat_vec (oc2) ((concat_vec (oc1) (oc0))))).

Definition aes_shift_rows_inv (x : mword 128) : mword 128 :=
   let ic3 : bits 32 := aes_get_column (x) (3) in
   let ic2 : bits 32 := aes_get_column (x) (2) in
   let ic1 : bits 32 := aes_get_column (x) (1) in
   let ic0 : bits 32 := aes_get_column (x) (0) in
   let oc0 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic1) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic2) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic3) (15) (8))) ((subrange_vec_dec (ic0) (7) (0))))))) in
   let oc1 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic2) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic3) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic0) (15) (8))) ((subrange_vec_dec (ic1) (7) (0))))))) in
   let oc2 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic3) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic0) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic1) (15) (8))) ((subrange_vec_dec (ic2) (7) (0))))))) in
   let oc3 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic0) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic1) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic2) (15) (8))) ((subrange_vec_dec (ic3) (7) (0))))))) in
   concat_vec (oc3) ((concat_vec (oc2) ((concat_vec (oc1) (oc0))))).

Definition aes_subbytes_fwd (x : mword 128) : mword 128 :=
   let oc0 : bits 32 := aes_subword_fwd ((aes_get_column (x) (0))) in
   let oc1 : bits 32 := aes_subword_fwd ((aes_get_column (x) (1))) in
   let oc2 : bits 32 := aes_subword_fwd ((aes_get_column (x) (2))) in
   let oc3 : bits 32 := aes_subword_fwd ((aes_get_column (x) (3))) in
