Definition legalize_smcntrpmf (c : mword 64) (value : mword 64) : M (mword 64) :=
   let v := Mk_CountSmcntrpmf (value) in
   (currentlyEnabled (Ext_S)) >>= fun (w__0 : bool) =>
   let w__1 : mword 1 := if w__0 then _get_CountSmcntrpmf_SINH (v) else ('b"0") in
   (currentlyEnabled (Ext_U)) >>= fun (w__2 : bool) =>
   let w__3 : mword 1 := if w__2 then _get_CountSmcntrpmf_UINH (v) else ('b"0") in
   (currentlyEnabled (Ext_H)) >>= fun (w__4 : bool) =>
   let w__5 : mword 1 := if w__4 then _get_CountSmcntrpmf_VSINH (v) else ('b"0") in
   (currentlyEnabled (Ext_H)) >>= fun (w__6 : bool) =>
   let w__7 : mword 1 := if w__6 then _get_CountSmcntrpmf_VUINH (v) else ('b"0") in
   returnM ((_update_CountSmcntrpmf_VUINH
               ((_update_CountSmcntrpmf_VSINH
                   ((_update_CountSmcntrpmf_UINH
                       ((_update_CountSmcntrpmf_SINH
                           ((_update_CountSmcntrpmf_MINH (c) ((_get_CountSmcntrpmf_MINH (v)))))
                           (w__1))) (w__3))) (w__5))) (w__7))).

Definition counter_priv_filter_bit (reg : mword 64) (priv : Privilege) : mword 1 :=
   match priv with
   | Machine => _get_CountSmcntrpmf_MINH (reg)
   | Supervisor => _get_CountSmcntrpmf_SINH (reg)
   | VirtualSupervisor => _get_CountSmcntrpmf_VSINH (reg)
   | User => _get_CountSmcntrpmf_UINH (reg)
   | VirtualUser => _get_CountSmcntrpmf_VUINH (reg)
   end.

