Definition undefined_ntl_type '(tt : unit) : M (ntl_type) :=
   (internal_pick ([NTL_P1; NTL_PALL; NTL_S1; NTL_ALL]))  : M (ntl_type).

Definition ntl_name_backwards (arg_ : string) : M (ntl_type) :=
   let p0_ := arg_ in
   (if generic_eq (p0_) ("p1") then returnM (NTL_P1)
    else if generic_eq (p0_) ("pall") then returnM (NTL_PALL)
    else if generic_eq (p0_) ("s1") then returnM (NTL_S1)
    else if generic_eq (p0_) ("all") then returnM (NTL_ALL)
