Definition within_mmio_readable (addr : physaddr) (width : Z) (*(0 <? width) && (width <=? 4096)*)
: M (bool) :=
   (if get_config_rvfi (tt) then returnM (false)
    else
      (or_boolM ((within_clint (addr) (width))  : M (bool))
         ((or_boolM ((within_sig (addr) (width))  : M (bool))
             ((and_boolM ((within_htif_readable (addr) (width))  : M (bool))
                 (returnM (((Z.leb (1) ((__id (width))))  : bool))))
              : M (bool)))
          : M (bool)))
       : M (bool))
    : M (bool).

Definition within_mmio_writable (addr : physaddr) (width : Z) (*(0 <? width) && (width <=? 4096)*)
: M (bool) :=
