    else
      (or_boolM ((within_clint (addr) (width))  : M (bool))
         ((or_boolM ((within_sig (addr) (width))  : M (bool))
             ((and_boolM ((within_htif_writable (addr) (width))  : M (bool))
                 (returnM (((Z.leb ((__id (width))) (8))  : bool))))
              : M (bool)))
          : M (bool)))
       : M (bool))
    : M (bool).

Definition mmio_read (access : MemoryAccessType mem_payload) (paddr : physaddr) (width : Z)
