            returnM ((Err (w__6))))
          : M (result (mword (8 * width)) ExceptionType))
       : M (result (mword (8 * width)) ExceptionType))
    : M (result (mword (8 * width)) ExceptionType).

Definition mmio_write (paddr : physaddr) (width : Z) (data : mword (8 * width)) (*width >=? 0*)
(*(0 <? width) && (width <=? 4096)*)
