   (if eq_vec (p0_) (('b"01")) then returnM (CSRRW)
    else if eq_vec (p0_) (('b"10")) then returnM (CSRRS)
    else if eq_vec (p0_) (('b"11")) then returnM (CSRRC)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (csrop).

Definition encdec_csrop_forwards_matches (arg_ : csrop) : bool :=
   match arg_ with | CSRRW => true | CSRRS => true | CSRRC => true end.

Definition encdec_csrop_backwards_matches (arg_ : mword 2) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"01")) then true
   else if eq_vec (p0_) (('b"10")) then true
   else if eq_vec (p0_) (('b"11")) then true
   else false.

Definition csr_access_type (op : csrop) (rd_is_x0 : bool) (rs1_imm_is_zero : bool) : CSRAccessType :=
   match (op, rd_is_x0, rs1_imm_is_zero) with
   | (CSRRW, true, _) => CSRWrite
   | (CSRRW, false, _) => CSRReadWrite
   | (CSRRS, _, true) => CSRRead
   | (CSRRC, _, true) => CSRRead
   | (CSRRS, _, false) => CSRReadWrite
   | (CSRRC, _, false) => CSRReadWrite
   end.

