Definition doCSR
(csr : mword 12) (rs1_val : mword 64) (rd : regidx) (op : csrop) (access_type : CSRAccessType)
: M (ExecutionResult) :=
   read_reg cur_privilege >>= fun (w__0 : Privilege) =>
   (check_CSR_result (csr) (w__0) (access_type)) >>= fun (w__1 : CSRCheckResult) =>
   match w__1 with
   | CSR_Illegal tt => returnM ((Illegal_Instruction (tt)))
   | CSR_Virtual tt => returnM ((Virtual_Instruction (tt)))
   | CSR_Check_OK tt =>
      read_reg cur_privilege >>= fun (w__2 : Privilege) =>
      (if not ((ext_check_CSR (csr) (w__2) (access_type))) then
         returnM ((Ext_CSR_Check_Failure (tt)))
       else
         (if generic_neq (access_type) (CSRWrite) return M (mword 64) then
            (read_CSR (csr))
             : M (mword 64)
          else returnM ((zeros' (64)))) >>= fun (read_val : xlenbits) =>
         let p0_ := csr in
         (if eq_vec (p0_) ((Ox"344")) return M (mword 64) then
            (read_mip (IncludePlatformInterrupts))
             : M (mword 64)
          else if eq_vec (p0_) ((Ox"144")) return M (mword 64) then
            (read_sip (IncludePlatformInterrupts))
             : M (mword 64)
          else returnM (read_val)) >>= fun (dest_val : xlenbits) =>
         (if generic_eq (access_type) (CSRRead) return M (ExecutionResult) then
            (csr_id_read_callback (csr) (dest_val)) >>
            (wX_bits (rd) (dest_val)) >> returnM (RETIRE_SUCCESS)
          else
            let write_val : xlenbits :=
              match op with
              | CSRRW => rs1_val
              | CSRRS => or_vec (read_val) (rs1_val)
              | CSRRC => and_vec (read_val) ((not_vec (rs1_val)))
              end in
            (write_CSR (csr) (write_val)) >>= fun (w__7 : result (mword 64) unit) =>
            match w__7 with
            | Ok final_val =>
               (wX_bits (rd) (dest_val)) >>
               (csr_id_write_callback (csr) (final_val)) >> returnM (RETIRE_SUCCESS)
            | Err tt => returnM ((Illegal_Instruction (tt)))
            end
             : M (ExecutionResult))
          : M (ExecutionResult))
       : M (ExecutionResult)
   end
    : M (ExecutionResult).

Definition csr_mnemonic_backwards (arg_ : string) : M (csrop) :=
   let p0_ := arg_ in
