    else if generic_eq (p0_) ("csrrs") then returnM (CSRRS)
    else if generic_eq (p0_) ("csrrc") then returnM (CSRRC)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
