   | ADDIW (imm, rs1, rd) => (execute_ADDIW (imm) (rs1) (rd))  : M (ExecutionResult)
   | RTYPEW (rs2, rs1, rd, op) => (execute_RTYPEW (rs2) (rs1) (rd) (op))  : M (ExecutionResult)
   | SHIFTIWOP (shamt, rs1, rd, op) =>
