   | FENCE_TSO arg0 => (execute_FENCE_TSO (arg0))  : M (ExecutionResult)
   | FENCE (_fm, pred, succ, _rs, _rd) =>
      (execute_FENCE (_fm) (pred) (succ) (_rs) (_rd))  : M (ExecutionResult)
   | ECALL arg0 => (execute_ECALL (arg0))  : M (ExecutionResult)
   | MRET arg0 => (execute_MRET (arg0))  : M (ExecutionResult)
   | SRET arg0 => (execute_SRET (arg0))  : M (ExecutionResult)
   | EBREAK arg0 => (execute_EBREAK (arg0))  : M (ExecutionResult)
   | WFI arg0 => (execute_WFI (arg0))  : M (ExecutionResult)
