Definition hart_is_active (s : HartState) : bool :=
   match s with | HART_ACTIVE tt => true | HART_WAITING _ => false end.

Definition hart_is_waiting (s : HartState) : bool :=
   match s with | HART_ACTIVE tt => false | HART_WAITING _ => true end.

