Definition run_hart_waiting
(_step_no : Z) (wr : WaitReason) (instbits : mword 32) (exit_wait : bool) (*0 <=? _step_no*)
: M (Step) :=
   (shouldWakeForInterrupt (tt)) >>= fun (w__0 : bool) =>
   (if w__0 return M (Step) then
      (if get_config_print_instr (tt) return M (unit) then
         ((read_reg PC)  : M (mword 64)) >>= fun (w__1 : mword 64) =>
         returnM ((print_endline
                     ((String.append ("interrupt exit from ")
                         ((String.append ((wait_name_forwards (wr)))
                             ((String.append (" state at PC ") ((string_of_bits (w__1)))))))))))
       else returnM (tt)) >>
      write_reg hart_state (HART_ACTIVE (tt)) >>
      returnM ((Step_Execute ((Retire_Success (tt), instbits))))
    else
      match (wr, valid_reservation (tt), exit_wait) with
      | (WAIT_WRS_STO, false, _) =>
         (if get_config_print_instr (tt) return M (unit) then
            ((read_reg PC)  : M (mword 64)) >>= fun (w__2 : mword 64) =>
            returnM ((print_endline
                        ((String.append ("reservation invalid exit from ")
                            ((String.append ((wait_name_forwards (WAIT_WRS_STO)))
                                ((String.append (" state at PC ") ((string_of_bits (w__2)))))))))))
          else returnM (tt)) >>
         write_reg hart_state (HART_ACTIVE (tt)) >>
         returnM ((Step_Execute ((Retire_Success (tt), instbits))))
