           ((liftR (read_reg PC))  : MR (Step) (mword 64)) >>= fun (w__17 : mword 64) =>
           liftR ((instruction_to_str (instruction))) >>= fun (w__18 : string) =>
           ((liftR (read_reg PC))  : MR (Step) (mword 64)) >>= fun (w__19 : mword 64) =>
           returnR (Step) ((print_log_instr
                              ((String.append ("[")
                                  ((String.append ((dec_str (step_no)))
                                      ((String.append ("] [")
                                          ((String.append (w__16)
                                              ((String.append ("]: ")
                                                  ((String.append ((string_of_bits (w__17)))
                                                      ((String.append (" (")
                                                          ((String.append ((string_of_bits (w)))
                                                              ((String.append (") ") (w__18)))))))))))))))))))
                              ((zero_extend' (64) (w__19)))))
