      (and_boolM (returnM (retired)) (read_reg minstret_increment  : M (bool))) >>= fun w__12 =>
      (if w__12 return M (unit) then
         ((read_reg minstret)  : M (mword 64)) >>= fun (w__13 : mword 64) =>
         write_reg minstret (add_vec_int (w__13) (1))
          : M (unit)
       else returnM (tt)) >>
      (if get_config_rvfi (tt) return M (unit) then
         ((read_reg rvfi_pc_data)  : M (mword 128)) >>= fun (w__14 : mword 128) =>
         (get_arch_pc (tt)) >>= fun (w__15 : mword 64) =>
         write_reg
           rvfi_pc_data
           (update_subrange_vec_dec (w__14) (127) (64) ((zero_extend' (64) (w__15))))
          : M (unit)
       else returnM (tt)) >>
      let '(_) := (ext_post_step_hook (tt))  : unit in
      let '(_) := (if retired then instret_callback (tt) else tt)  : unit in
      returnM (false)
   end
    : M (bool).

Definition loop '(tt : unit) : M (unit) :=
   let i : Z := 0 in
   let step_no : Z := 0 in
   (whileMT
     (i, step_no)
     (fun '(i, step_no) => 100)
     (fun '(i, step_no) =>
       (read_reg htif_done >>= fun (w__0 : bool) => returnM (((not (w__0))  : bool)))
        : M (bool))
     (fun '(i, step_no) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        (try_step (step_no) (true)) >>= fun stepped =>
        (if stepped return M (Z) then
           let step_no : Z := Z.add (step_no) (1) in
           let '(_) := (if get_config_print_instr (tt) then print_step (tt) else tt)  : unit in
           (cycle_count (tt)) >> returnM (step_no)
         else returnM (step_no)) >>= fun (step_no : Z) =>
        read_reg htif_done >>= fun (w__1 : bool) =>
        (if w__1 return M (Z) then
           ((read_reg htif_exit_code)  : M (mword 64)) >>= fun (w__2 : mword 64) =>
           let exit_val := uint (w__2) in
           (if Z.eqb (exit_val) (0) then returnM ((print ("SUCCESS")))
            else
              ((read_reg htif_exit_code)  : M (mword 64)) >>= fun (w__3 : mword 64) =>
              returnM ((print_endline
                          ((String.append ("FAILURE: ")
                              ((String.append ((dec_str (exit_val)))
                                  ((String.append (" (")
                                      ((String.append ((string_of_bits (w__3))) (")")))))))))))) >>
           returnM (i)
         else
           let i : Z := Z.add (i) (1) in
           (if Z.eqb (i) (plat_insns_per_tick) return M (Z) then (tick_clock (tt)) >> returnM (0)
            else returnM (i))
            : M (Z)) >>= fun (i : Z) =>
        returnM ((i, step_no)))
        : M ((Z * Z)))) >>= fun '((i, step_no)
   : (Z * Z)) =>
   returnM (tt).

