Definition check_vext_config '(tt : unit) : M (bool) :=
   let valid : bool := true in
   let valid : bool :=
     if andb ((vector_support_ge (vector_support_level) (Integer)))
          (((Z.ltb ((elen_exp  : Z)) (5))
           : bool)) then
       let valid : bool := false in
