   let max_index_eew := 6  : Z in
   let valid : bool :=
     if Z.gtb (max_index_eew) (elen_exp) then
       let valid : bool := false in
       let '(_) :=
         (print_endline
            ((String.append ("The maximum index EEW is 2^")
                ((String.append ((dec_str (max_index_eew)))
                    ((String.append (" but ELEN is 2^")
                        ((String.append ((dec_str (elen_exp)))
                            (": the index EEW must not exceed ELEN."))))))))))
          : unit in
       valid
     else if Z.ltb (max_index_eew) (3) then
       let valid : bool := false in
       let '(_) :=
         (print_endline
            ((String.append ("The maximum index EEW is 2^")
                ((String.append ((dec_str (max_index_eew))) (" but it should be at least 2^3."))))))
          : unit in
       valid
     else valid in
   let valid : bool :=
     if andb ((vector_support_ge (vector_support_level) (Float_single))) ((not ((true  : bool))))
     then
       let valid : bool := false in
       let '(_) :=
         (print_endline ("Zve*f is enabled but F is disabled: supporting Zve*f requires F."))
          : unit in
       valid
     else valid in
   (if vector_support_ge (vector_support_level) (Float_double) return M (bool) then
      let valid : bool :=
        if Z.ltb ((elen_exp  : Z)) (6) then
          let valid : bool := false in
