Definition check_pma_region (region : PMA_Region) : bool :=
   pure_early_return
     ((if neq_vec ((subrange_vec_dec (region.(PMA_Region_base)) ((Z.sub (pagesize_bits) (1))) (0)))
            ((zeros' ((Z.add ((Z.sub ((Z.sub (12) (1))) (0))) (1))))) then
         let '(_) :=
           (print_endline
              ((String.append ("Memory region starting at ")
                  ((String.append ((string_of_bits (region.(PMA_Region_base))))
                      (" does not start on a 4K (page) boundary."))))))
            : unit in
         inr (false)
       else if neq_vec
                 ((subrange_vec_dec (region.(PMA_Region_size)) ((Z.sub (pagesize_bits) (1))) (0)))
                 ((zeros' ((Z.add ((Z.sub ((Z.sub (12) (1))) (0))) (1))))) then
         let '(_) :=
           (print_endline
              ((String.append ("Memory region starting at ")
                  ((String.append ((string_of_bits (region.(PMA_Region_base))))
                      ((String.append (" with size ")
                          ((String.append ((string_of_bits (region.(PMA_Region_size))))
                              (" does not end on a 4K (page) boundary."))))))))))
            : unit in
         inr (false)
       else
         let pma := region.(PMA_Region_attributes) in
         match pma.(PMA_mem_type) with
         | MainMemory =>
            (if not
                  ((andb (pma.(PMA_readable))
                      ((andb (pma.(PMA_writable))
                          ((andb (pma.(PMA_read_idempotent)) (pma.(PMA_write_idempotent))))))))
               return
               sum (bool) (unit) then
               let '(_) :=
                 (print_endline
                    ((String.append ("Memory region starting at ")
                        ((String.append ((string_of_bits (region.(PMA_Region_base))))
                            ((String.append (" is marked as ")
                                ((String.append
                                    ((memory_region_type_str_forwards (pma.(PMA_mem_type))))
                                    (" but is not readable, read-idempotent, writable, and write-idempotent."))))))))))
                  : unit in
               (inl (false  : bool) : sum bool unit)
                : sum (bool) (unit)
             else inr (tt))
             : sum (bool) (unit)
         | IOMemory => inr (tt)
         end >>$
         inr (true))
      : sum (bool) (bool)).

