   returnM (({| pma_check_opts_ziccamoa := w__0;
                pma_check_opts_ziccamoc := w__1;
                pma_check_opts_ziccif := w__2;
                pma_check_opts_zicclsm := w__3;
                pma_check_opts_ziccrse := w__4;
                pma_check_opts_ssccptr := w__5;
                pma_check_opts_svadu := w__6 |})).

Fixpoint check_pma_regions
(regions : list PMA_Region) (prev_base : mword 64) (prev_size : mword 64)
(check_opts : pma_check_opts) (found_valid_svadu_pma : bool)
: bool :=
   pure_early_return
     (match regions with
     | [] =>
        inr ((if andb (check_opts.(pma_check_opts_svadu)) ((not (found_valid_svadu_pma))) then
                let '(_) :=
                  (print_endline
                     ("The Svadu extension is enabled but no memory region supports hardware page-table writes: Svadu requires at least one region provide this support."))
                   : unit in
                false
              else true))
     | region :: rest =>
        (if zopz0zI_u (region.(PMA_Region_base)) ((add_vec (prev_base) (prev_size))) then
           let '(_) :=
             (print_endline
                ((String.append ("Memory region starting at ")
                    ((String.append ((string_of_bits (region.(PMA_Region_base))))
                        ((String.append
                            (" is not above the end of the previous region starting at ")
                            ((String.append ((string_of_bits (prev_base)))
                                ((String.append (" and ending at ")
                                    ((String.append
                                        ((string_of_bits ((add_vec (prev_base) (prev_size))))) ("."))))))))))))))
              : unit in
           inr (false)
         else if not ((check_pma_region (region))) then inr (false)
         else
           let attributes := region.(PMA_Region_attributes) in
           (if andb ((generic_eq (attributes.(PMA_mem_type)) (MainMemory)))
                 ((andb (attributes.(PMA_cacheable)) (attributes.(PMA_coherent))))
              return
              sum (bool) (unit) then
              (if andb (check_opts.(pma_check_opts_ziccamoa))
                    ((pma_atomicity_support_lt (attributes.(PMA_atomic_support)) (AMOArithmetic)))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              ((String.append (" is coherent and cacheable with ")
                                  ((String.append
                                      ((atomic_support_str_forwards
                                          (attributes.(PMA_atomic_support))))
                                      (" atomicity support, but Ziccamoa is enabled which requires AMOArithmetic support."))))))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else if andb (check_opts.(pma_check_opts_ziccamoc))
                         ((generic_neq (attributes.(PMA_atomic_support)) (AMOCASQ)))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              ((String.append (" is coherent and cacheable with ")
                                  ((String.append
                                      ((atomic_support_str_forwards
                                          (attributes.(PMA_atomic_support))))
                                      (" atomicity support, but Ziccamoc is enabled which requires AMOCASQ support."))))))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else if andb (check_opts.(pma_check_opts_ziccif))
                         ((not (attributes.(PMA_executable))))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              (" is coherent and cacheable with no instruction fetch support, but Ziccif is enabled which requires this support."))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else
               (if check_opts.(pma_check_opts_zicclsm) return sum (bool) (unit) then
                  (if misaligned_exception_is_access_fault
                        (attributes.(PMA_misaligned_exceptions).(PMAMisalignedExceptions_load_store))
                     return
                     sum (bool) (unit) then
                     let '(_) :=
                       (print_endline
                          ((String.append ("Main memory region starting at ")
                              ((String.append ((string_of_bits (region.(PMA_Region_base))))
                                  (" is coherent and cacheable with access faults for misaligned scalar loads/stores, but Zicclsm is enabled which requires no exceptions or only misaligned exceptions for such accesses."))))))
                        : unit in
                     (inl (false  : bool) : sum bool unit)
                      : sum (bool) (unit)
                   else if misaligned_exception_is_access_fault
                             (attributes.(PMA_misaligned_exceptions).(PMAMisalignedExceptions_vector))
                     return
                     sum (bool) (unit) then
                     let '(_) :=
                       (print_endline
                          ((String.append ("Main memory region starting at ")
                              ((String.append ((string_of_bits (region.(PMA_Region_base))))
                                  (" is coherent and cacheable with access faults for misaligned vector loads/stores, but Zicclsm is enabled which requires no exceptions or only misaligned exceptions for such accesses."))))))
                        : unit in
                     (inl (false  : bool) : sum bool unit)
                      : sum (bool) (unit)
                   else inr (tt))
                   : sum (bool) (unit)
                else inr (tt)) >>$
               if andb (check_opts.(pma_check_opts_ziccrse))
                    ((generic_neq (attributes.(PMA_reservability)) (RsrvEventual)))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              ((String.append (" is coherent and cacheable with ")
                                  ((String.append
                                      ((reservability_str_forwards (attributes.(PMA_reservability))))
                                      (" reservability support, but Ziccrse is enabled which requires RsrvEventual support."))))))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else if andb (check_opts.(pma_check_opts_ssccptr))
                         ((not (attributes.(PMA_supports_pte_read))))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              (" is coherent and cacheable without hardware page-table read support, but Ssccptr is enabled which requires this support."))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else inr (tt))
               : sum (bool) (unit)
            else inr (tt)) >>$
           let found_valid_svadu_pma :=
             orb (found_valid_svadu_pma)
               ((andb (attributes.(PMA_supports_pte_write))
                   ((generic_eq (attributes.(PMA_reservability)) (RsrvEventual))))) in
           inr ((check_pma_regions (rest) (region.(PMA_Region_base)) (region.(PMA_Region_size))
                   (check_opts) (found_valid_svadu_pma))))
         : sum (bool) (bool)
     end
      : sum (bool) (bool)).

Definition within_configured_pma_memory
(component : string) (mem_type_opt : option MemoryRegionType) (addr : mword 64) (size : mword 64)
: M (bool) :=
   let valid : bool := true in
   read_reg pma_regions >>= fun (w__0 : list PMA_Region) =>
   let valid : bool :=
     match (matching_pma_region_bits_range (w__0) (addr) (size), mem_type_opt) with
     | (None, _) =>
        let valid : bool := false in
        let '(_) :=
          (print_endline
             ((String.append ("The ")
                 ((String.append (component)
                     (" for the platform is not in a defined memory region."))))))
           : unit in
        valid
     | (Some region, Some mem_type) =>
        if generic_neq (region.(PMA_Region_attributes).(PMA_mem_type)) (mem_type) then
          let valid : bool := false in
          let '(_) :=
            (print_endline
               ((String.append ("The ")
                   ((String.append (component)
                       ((String.append (" for the platform is in a memory region starting at ")
                           ((String.append ((string_of_bits (region.(PMA_Region_base))))
                               ((String.append (" which is not a ")
                                   ((String.append ((memory_region_type_str_forwards (mem_type)))
                                       (" region."))))))))))))))
             : unit in
          valid
        else valid
     | (Some _, _) => valid
     end in
   returnM (valid).

Definition dtb_within_configured_pma_memory (addr : mword 64) (size : mword 64) : M (bool) :=
   (within_configured_pma_memory ("DTB") (None) (addr) (size))  : M (bool).

Definition check_mem_layout '(tt : unit) : M (bool) :=
   read_reg pma_regions >>= fun (w__0 : list PMA_Region) =>
   (if generic_eq (w__0) ([]) then
      let '(_) := (print_endline ("No memory regions specified."))  : unit in
      returnM (false)
    else
      let check_opts : pma_check_opts :=
        {| pma_check_opts_ziccamoa := true;
           pma_check_opts_ziccamoc := true;
           pma_check_opts_ziccif := true;
           pma_check_opts_zicclsm := true;
           pma_check_opts_ziccrse := true;
           pma_check_opts_ssccptr := true;
           pma_check_opts_svadu := true |} in
      read_reg pma_regions >>= fun (w__1 : list PMA_Region) =>
      let pmas_ok := check_pma_regions (w__1) ((zeros' (64))) ((zeros' (64))) (check_opts) (false) in
      let clint_supported : bool := true in
      (or_boolM (returnM ((not (clint_supported))))
         ((to_bits_checked (64) ((33554432  : Z))) >>= fun (w__2 : mword 64) =>
          (to_bits_checked (64) ((786432  : Z))) >>= fun (w__3 : mword 64) =>
          (within_configured_pma_memory ("CLINT (platform.clint)") ((Some (IOMemory))) (w__2) (w__3))
           : M (bool))) >>= fun clint_ok =>
      let sig_supported : bool := false in
      (or_boolM (returnM ((not (sig_supported))))
         ((to_bits_checked (64) ((201326592  : Z))) >>= fun (w__5 : mword 64) =>
          (within_configured_pma_memory
             ("simple interrupt generator (platform.simple_interrupt_generator)")
             ((Some (IOMemory))) (w__5) ((zero_extend' (64) (plat_sig_size))))
           : M (bool))) >>= fun sig_ok =>
      returnM ((andb (pmas_ok) ((andb (clint_ok) (sig_ok))))))
    : M (bool).

Definition check_pmp '(tt : unit) : bool :=
